  1→import { createHmac } from 'node:crypto';
  2→import { NextRequest } from 'next/server';
  3→import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
  4→import { POST } from './route';
  5→
  6→// ---------------------------------------------------------------------------
  7→// Helpers
  8→// ---------------------------------------------------------------------------
  9→
 10→function makeRequest(body: unknown, headers: Record<string, string> = {}): NextRequest {
 11→  const json = JSON.stringify(body);
 12→  return new NextRequest('https://tpmjs.com/api/sentry/webhook', {
 13→    method: 'POST',
 14→    headers: { 'Content-Type': 'application/json', ...headers },
 15→    body: json,
 16→  });
 17→}
 18→
 19→function hmac(secret: string, body: unknown): string {
 20→  return createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');
 21→}
 22→
 23→const MOCK_SECRET = 'test-webhook-secret';
 24→const MOCK_GH_TOKEN = 'ghp_test123';
 25→const MOCK_SENTRY_TOKEN = 'sntrys_test456';
 26→
 27→function issueHeaders(body: unknown, resource = 'issue'): Record<string, string> {
 28→  return {
 29→    'sentry-hook-resource': resource,
 30→    'sentry-hook-signature': hmac(MOCK_SECRET, body),
 31→  };
 32→}
 33→
 34→const MOCK_GH_ISSUE_RESPONSE = { number: 42, html_url: 'https://github.com/tpmjs/tpmjs/issues/42' };
 35→
 36→// ---------------------------------------------------------------------------
 37→// Setup / Teardown
 38→// ---------------------------------------------------------------------------
 39→
 40→let savedEnv: NodeJS.ProcessEnv;
 41→let fetchSpy: ReturnType<typeof vi.fn>;
 42→
 43→beforeEach(() => {
 44→  savedEnv = { ...process.env };
 45→  process.env.SENTRY_WEBHOOK_SECRET = MOCK_SECRET;
 46→  process.env.GITHUB_TOKEN_ISSUES = MOCK_GH_TOKEN;
 47→  process.env.SENTRY_AUTH_TOKEN = MOCK_SENTRY_TOKEN;
 48→
 49→  fetchSpy = vi.fn();
 50→  vi.stubGlobal('fetch', fetchSpy);
 51→
 52→  // Default: GitHub issue creation succeeds
 53→  fetchSpy.mockResolvedValue(new Response(JSON.stringify(MOCK_GH_ISSUE_RESPONSE), { status: 201 }));
 54→});
 55→
 56→afterEach(() => {
 57→  process.env = savedEnv;
 58→  vi.restoreAllMocks();
 59→});
 60→
 61→// ---------------------------------------------------------------------------
 62→// Tests
 63→// ---------------------------------------------------------------------------
 64→
 65→describe('POST /api/sentry/webhook', () => {
 66→  // 1. Settings validation (no resource/signature headers)
 67→  it('returns ok for settings validation requests', async () => {
 68→    const res = await POST(makeRequest({}));
 69→    expect(res.status).toBe(200);
 70→    expect(await res.json()).toEqual({ ok: true });
 71→    expect(fetchSpy).not.toHaveBeenCalled();
 72→  });
 73→
 74→  // 2. Missing env vars
 75→  it('returns 500 when env vars are missing', async () => {
 76→    delete process.env.SENTRY_WEBHOOK_SECRET;
 77→    const body = {};
 78→    const res = await POST(
 79→      makeRequest(body, {
 80→        'sentry-hook-resource': 'issue',
 81→        'sentry-hook-signature': 'anything',
 82→      })
 83→    );
 84→    expect(res.status).toBe(500);
 85→    expect(await res.json()).toEqual({ error: 'Not configured' });
 86→  });
 87→
 88→  // 3. Missing signature header
 89→  it('returns 401 when signature header is missing', async () => {
 90→    const res = await POST(
 91→      makeRequest({}, { 'sentry-hook-resource': 'issue' })
 92→    );
 93→    expect(res.status).toBe(401);
 94→    expect(await res.json()).toEqual({ error: 'Missing signature' });
 95→  });
 96→
 97→  // 4. Valid HMAC signature passes
 98→  it('accepts requests with valid HMAC signature', async () => {
 99→    const body = {
100→      action: 'created',
101→      data: {
102→        issue: {
103→          title: 'TypeError: Cannot read properties',
104→          culprit: 'src/app/page.tsx',
105→          level: 'error',
106→          platform: 'node',
107→          permalink: 'https://sentry.io/issues/123',
108→          firstSeen: '2025-01-01T00:00:00Z',
109→          count: 5,
110→        },
111→      },
112→    };
113→    const res = await POST(makeRequest(body, issueHeaders(body)));
114→    expect(res.status).toBe(200);
115→    const json = await res.json();
116→    expect(json.ok).toBe(true);
117→    expect(json.issue).toBe(42);
118→  });
119→
120→  // 5. Invalid HMAC signature still processes (logs warning)
121→  it('processes requests with invalid signature (logs warning)', async () => {
122→    const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
123→    const body = {
124→      action: 'created',
125→      data: {
126→        issue: {
127→          title: 'Error',
128→          culprit: 'unknown',
129→          level: 'error',
130→        },
131→      },
132→    };
133→    const res = await POST(
134→      makeRequest(body, {
135→        'sentry-hook-resource': 'issue',
136→        'sentry-hook-signature': 'invalid-signature',
137→      })
138→    );
139→    expect(res.status).toBe(200);
140→    expect(warnSpy).toHaveBeenCalledWith(
141→      expect.stringContaining('Signature mismatch')
142→    );
143→  });
144→
145→  // 6. Issue `created` → GitHub issue with auto-fix + production-error labels
146→  it('creates GitHub issue with correct labels for created event', async () => {
147→    const body = {
148→      action: 'created',
149→      data: {
150→        issue: {
151→          title: 'ReferenceError: foo is not defined',
152→          culprit: 'src/utils/foo.ts',
153→          level: 'error',
154→          platform: 'javascript',
155→          permalink: 'https://sentry.io/issues/456',
156→          firstSeen: '2025-06-01T12:00:00Z',
157→          count: 3,
158→        },
159→      },
160→    };
161→    const res = await POST(makeRequest(body, issueHeaders(body)));
162→    expect(res.status).toBe(200);
163→
164→    const [url, opts] = fetchSpy.mock.calls[0];
165→    expect(url).toBe('https://api.github.com/repos/tpmjs/tpmjs/issues');
166→    const ghBody = JSON.parse(opts.body);
167→    expect(ghBody.title).toBe('[Sentry] ReferenceError: foo is not defined');
168→    expect(ghBody.labels).toEqual(['auto-fix', 'production-error']);
169→    expect(ghBody.body).toContain('src/utils/foo.ts');
170→  });
171→
172→  // 7. Issue `regression` → adds regression label
173→  it('adds regression label for regression events', async () => {
174→    const body = {
175→      action: 'regression',
176→      data: {
177→        issue: {
178→          title: 'Regression bug',
179→          culprit: 'src/api/route.ts',
180→          level: 'error',
181→          platform: 'node',
182→          permalink: 'https://sentry.io/issues/789',
183→          firstSeen: '2025-06-01T12:00:00Z',
184→          count: 10,
185→        },
186→      },
187→    };
188→    const res = await POST(makeRequest(body, issueHeaders(body)));
189→    expect(res.status).toBe(200);
190→
191→    const ghBody = JSON.parse(fetchSpy.mock.calls[0][1].body);
192→    expect(ghBody.labels).toEqual(['auto-fix', 'production-error', 'regression']);
193→    expect(ghBody.body).toContain('Regression');
194→    expect(ghBody.body).toContain('previously resolved');
195→  });
196→
197→  // 8. Non-actionable issue event (`resolved`) → skips
198→  it('skips non-actionable issue events', async () => {
199→    const body = { action: 'resolved', data: { issue: { title: 'Fixed' } } };
200→    const res = await POST(makeRequest(body, issueHeaders(body)));
201→    expect(res.status).toBe(200);
202→    const json = await res.json();
203→    expect(json.skipped).toBe(true);
204→    expect(json.reason).toBe('issue/resolved');
205→    expect(fetchSpy).not.toHaveBeenCalled();
206→  });
207→
