let fetchSpy: ReturnType<typeof vi.fn>;

beforeEach(() => {
  savedEnv = { ...process.env };
  process.env.SENTRY_WEBHOOK_SECRET = MOCK_SECRET;
  process.env.GITHUB_TOKEN_ISSUES = MOCK_GH_TOKEN;
  process.env.SENTRY_AUTH_TOKEN = MOCK_SENTRY_TOKEN;

  fetchSpy = vi.fn();
  vi.stubGlobal('fetch', fetchSpy);

  // Default: GitHub issue creation succeeds
  fetchSpy.mockResolvedValue(new Response(JSON.stringify(MOCK_GH_ISSUE_RESPONSE), { status: 201 }));
});

afterEach(() => {
  process.env = savedEnv;
  vi.restoreAllMocks();
});

