30→ * Fire-and-forget view tracking. Upserts into PageView with daily bucket.
31→ */
32→export async function POST(request: NextRequest) {
33→  try {
34→    const body = await request.json();
35→    const { entityType, entityId } = body;
36→
37→    // Validate input
38→    if (!entityType || !entityId) {
39→      return NextResponse.json({ error: 'Missing entityType or entityId' }, { status: 400 });
40→    }
41→
42→    if (!VALID_ENTITY_TYPES.includes(entityType)) {
43→      return NextResponse.json({ error: 'Invalid entityType' }, { status: 400 });
44→    }
45→
46→    // Rate-limit: 1 view per entity per IP per hour
47→    const clientId = getClientId(request);
48→    const dedupKey = `${clientId}:${entityType}:${entityId}`;
49→    const lastView = recentViews.get(dedupKey);
50→
51→    if (lastView && Date.now() - lastView < 3600_000) {
52→      return NextResponse.json({ ok: true, deduped: true });
53→    }
54→
55→    recentViews.set(dedupKey, Date.now());
56→
57→    // Today's date bucket (midnight UTC)
58→    const today = new Date();
59→    today.setUTCHours(0, 0, 0, 0);
60→
61→    // Upsert page view (fire-and-forget style, don't await in production but we need to for correctness)
62→    await prisma.pageView.upsert({
