  8→/**
  9→ * POST /api/sync/execution-rollup
 10→ * Daily cron: aggregates ExecutionEvent counts into denormalized fields
 11→ * on Tool, Collection, and Agent models.
 12→ */
 13→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: cron handler with sequential entity type processing
 14→export async function POST(request: NextRequest) {
 15→  const startTime = Date.now();
 16→
 17→  // Verify cron secret
 18→  const authHeader = request.headers.get('authorization');
 19→  const cronSecret = process.env.CRON_SECRET;
 20→
 21→  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
 22→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 23→  }
 24→
 25→  try {
 26→    let totalUpdated = 0;
 27→
 28→    // 1. Aggregate execution counts by toolId
 29→    const toolCounts = await prisma.executionEvent.groupBy({
 30→      by: ['toolId'],
 31→      where: { toolId: { not: null } },
 32→      _count: { id: true },
 33→    });
 34→
 35→    for (const tc of toolCounts) {
 36→      if (!tc.toolId || tc._count.id === 0) continue;
 37→      try {
 38→        await prisma.tool.update({
 39→          where: { id: tc.toolId },
 40→          data: { executionCount: tc._count.id },
 41→        });
 42→        totalUpdated++;
 43→      } catch {
 44→        // Entity may have been deleted - skip silently
 45→      }
 46→    }
 47→
 48→    // 2. Aggregate execution counts by collectionId
 49→    const collectionCounts = await prisma.executionEvent.groupBy({
 50→      by: ['collectionId'],
 51→      where: { collectionId: { not: null } },
 52→      _count: { id: true },
 53→    });
 54→
 55→    for (const cc of collectionCounts) {
 56→      if (!cc.collectionId || cc._count.id === 0) continue;
 57→      try {
 58→        await prisma.collection.update({
 59→          where: { id: cc.collectionId },
 60→          data: { executionCount: cc._count.id },
 61→        });
 62→        totalUpdated++;
 63→      } catch {
 64→        // Entity may have been deleted - skip silently
 65→      }
 66→    }
 67→
 68→    // 3. Aggregate execution counts by agentId (agent_run events)
 69→    const agentExecCounts = await prisma.executionEvent.groupBy({
 70→      by: ['agentId'],
 71→      where: { agentId: { not: null } },
 72→      _count: { id: true },
 73→    });
 74→
 75→    for (const ac of agentExecCounts) {
 76→      if (!ac.agentId || ac._count.id === 0) continue;
 77→      try {
 78→        await prisma.agent.update({
 79→          where: { id: ac.agentId },
 80→          data: { executionCount: ac._count.id },
 81→        });
 82→        totalUpdated++;
 83→      } catch {
 84→        // Entity may have been deleted - skip silently
 85→      }
 86→    }
 87→
 88→    // 4. Count conversations per agent
 89→    const conversationCounts = await prisma.conversation.groupBy({
 90→      by: ['agentId'],
 91→      _count: { id: true },
 92→    });
 93→
 94→    for (const cc of conversationCounts) {
 95→      if (cc._count.id === 0) continue;
 96→      try {
 97→        await prisma.agent.update({
 98→          where: { id: cc.agentId },
 99→          data: { conversationCount: cc._count.id },
100→        });
101→        totalUpdated++;
102→      } catch {
103→        // Entity may have been deleted - skip silently
104→      }
105→    }
106→
107→    // 5. Count messages per agent (via conversations)
108→    const messageCounts = await prisma.message.groupBy({
109→      by: ['conversationId'],
110→      _count: { id: true },
111→    });
112→
113→    // Aggregate messages by agent
114→    const agentMessageMap = new Map<string, number>();
115→    if (messageCounts.length > 0) {
116→      const conversationIds = messageCounts.map((mc) => mc.conversationId);
117→      const conversations = await prisma.conversation.findMany({
118→        where: { id: { in: conversationIds } },
119→        select: { id: true, agentId: true },
120→      });
121→      const convToAgent = new Map(conversations.map((c) => [c.id, c.agentId]));
122→
123→      for (const mc of messageCounts) {
124→        const agentId = convToAgent.get(mc.conversationId);
125→        if (agentId) {
126→          agentMessageMap.set(agentId, (agentMessageMap.get(agentId) || 0) + mc._count.id);
127→        }
128→      }
129→    }
130→
131→    for (const [agentId, count] of agentMessageMap) {
132→      try {
133→        await prisma.agent.update({
134→          where: { id: agentId },
135→          data: { messageCount: count },
136→        });
137→        totalUpdated++;
138→      } catch {
139→        // Entity may have been deleted - skip silently
140→      }
141→    }
142→
143→    const durationMs = Date.now() - startTime;
144→
145→    return NextResponse.json({
146→      success: true,
147→      data: {
148→        totalUpdated,
149→        durationMs,
150→      },
151→    });
152→  } catch (error) {
153→    console.error('[sync/execution-rollup] Error:', error);
154→    return NextResponse.json(
155→      {
156→        success: false,
157→        error: error instanceof Error ? error.message : 'Unknown error',
158→      },
159→      { status: 500 }
160→    );
161→  }
162→}
