  1→import { prisma } from '@tpmjs/db';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→import { checkRateLimit } from '~/lib/rate-limit';
  4→
  5→export const runtime = 'nodejs';
  6→export const dynamic = 'force-dynamic';
  7→export const maxDuration = 30;
  8→
  9→/**
 10→ * GET /api/stats/tools
 11→ * Top tools by various metrics
 12→ *
 13→ * Query params:
 14→ * - sortBy: 'quality' | 'downloads' | 'executions' | 'recent' (default: 'quality')
 15→ * - limit: number (default: 20, max: 100)
 16→ * - category: filter by category
 17→ * - health: 'healthy' | 'broken' | 'unknown' - filter by health status
 18→ *
 19→ * Returns:
 20→ * - Top tools by quality score
 21→ * - Top tools by npm downloads
 22→ * - Most executed tools
 23→ * - Recently added tools
 24→ * - Tool category distribution
 25→ */
 26→export async function GET(request: NextRequest) {
 27→  const startTime = Date.now();
 28→
 29→  // Check rate limit
 30→  const rateLimitResponse = checkRateLimit(request);
 31→  if (rateLimitResponse) {
 32→    return rateLimitResponse;
 33→  }
 34→
 35→  try {
 36→    const { searchParams } = new URL(request.url);
 37→    const sortBy = searchParams.get('sortBy') || 'quality';
 38→    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 100);
 39→    const category = searchParams.get('category');
 40→    const healthFilter = searchParams.get('health');
 41→
 42→    const now = new Date();
 43→
 44→    // Build where clause
 45→    const whereClause: Record<string, unknown> = {};
 46→    if (category) {
 47→      whereClause.package = { category };
 48→    }
 49→    if (healthFilter === 'healthy') {
 50→      whereClause.importHealth = 'HEALTHY';
 51→      whereClause.executionHealth = 'HEALTHY';
 52→    } else if (healthFilter === 'broken') {
 53→      whereClause.OR = [{ importHealth: 'BROKEN' }, { executionHealth: 'BROKEN' }];
 54→    } else if (healthFilter === 'unknown') {
 55→      whereClause.OR = [{ importHealth: 'UNKNOWN' }, { executionHealth: 'UNKNOWN' }];
 56→    }
 57→
 58→    // Determine sort order
 59→    let orderBy: Record<string, unknown>[];
 60→    switch (sortBy) {
 61→      case 'downloads':
 62→        orderBy = [{ package: { npmDownloadsLastMonth: 'desc' } }, { qualityScore: 'desc' }];
 63→        break;
 64→      case 'recent':
 65→        orderBy = [{ createdAt: 'desc' }];
 66→        break;
 67→      default:
 68→        orderBy = [{ qualityScore: 'desc' }, { package: { npmDownloadsLastMonth: 'desc' } }];
 69→        break;
 70→    }
 71→
 72→    // For execution sorting, we need a different query
 73→    let tools;
 74→    let executionCounts: Map<string, number> = new Map();
 75→
 76→    if (sortBy === 'executions') {
 77→      // Get execution counts first
 78→      const execGroups = await prisma.simulation.groupBy({
 79→        by: ['toolId'],
 80→        _count: { id: true },
 81→        orderBy: { _count: { id: 'desc' } },
 82→        take: limit * 2, // Get more to account for filtering
 83→      });
 84→
 85→      const toolIds = execGroups.map((g) => g.toolId);
 86→      executionCounts = new Map(execGroups.map((g) => [g.toolId, g._count.id]));
 87→
 88→      tools = await prisma.tool.findMany({
 89→        where: {
 90→          id: { in: toolIds },
 91→          ...whereClause,
 92→        },
 93→        take: limit,
 94→        include: {
 95→          package: {
 96→            select: {
 97→              npmPackageName: true,
 98→              npmVersion: true,
 99→              npmDownloadsLastMonth: true,
100→              githubStars: true,
101→              category: true,
102→              tier: true,
103→              isOfficial: true,
104→              npmHomepage: true,
105→              npmRepository: true,
106→            },
107→          },
108→        },
109→      });
110→
111→      // Sort by execution count
112→      tools.sort((a, b) => (executionCounts.get(b.id) || 0) - (executionCounts.get(a.id) || 0));
113→    } else {
114→      tools = await prisma.tool.findMany({
115→        where: whereClause,
116→        orderBy,
117→        take: limit,
118→        include: {
119→          package: {
120→            select: {
121→              npmPackageName: true,
122→              npmVersion: true,
123→              npmDownloadsLastMonth: true,
124→              githubStars: true,
125→              category: true,
126→              tier: true,
127→              isOfficial: true,
128→              npmHomepage: true,
129→              npmRepository: true,
130→            },
131→          },
132→          _count: {
133→            select: { simulations: true },
134→          },
135→        },
136→      });
137→    }
138→
139→    // Get execution counts for non-execution sorted queries
140→    if (sortBy !== 'executions') {
141→      const toolIds = tools.map((t) => t.id);
142→      const execGroups = await prisma.simulation.groupBy({
143→        by: ['toolId'],
144→        where: { toolId: { in: toolIds } },
145→        _count: { id: true },
146→      });
147→      executionCounts = new Map(execGroups.map((g) => [g.toolId, g._count.id]));
148→    }
149→
150→    // Get category distribution
151→    const categoryDistribution = await prisma.package.groupBy({
152→      by: ['category'],
153→      _count: true,
154→      orderBy: { _count: { category: 'desc' } },
155→    });
156→
157→    // Format tools response
158→    const formattedTools = tools.map((tool, index) => ({
159→      rank: index + 1,
160→      id: tool.id,
161→      name: tool.name,
162→      description: tool.description,
163→      qualityScore: tool.qualityScore ? Number(tool.qualityScore) : null,
164→      importHealth: tool.importHealth,
165→      executionHealth: tool.executionHealth,
166→      lastHealthCheck: tool.lastHealthCheck,
167→      hasExtractedSchema: tool.schemaSource === 'extracted',
168→      package: {
169→        name: tool.package.npmPackageName,
170→        version: tool.package.npmVersion,
171→        category: tool.package.category,
172→        tier: tool.package.tier,
173→        isOfficial: tool.package.isOfficial,
174→        npmDownloadsLastMonth: tool.package.npmDownloadsLastMonth,
175→        githubStars: tool.package.githubStars,
176→        homepage: tool.package.npmHomepage,
177→        repository: tool.package.npmRepository,
178→      },
179→      executionCount: executionCounts.get(tool.id) || 0,
180→      createdAt: tool.createdAt,
181→    }));
182→
183→    // Format category distribution
184→    const formattedCategories = categoryDistribution.map((cat) => ({
185→      category: cat.category,
186→      packageCount: cat._count,
187→    }));
188→
189→    const processingTime = Date.now() - startTime;
190→
191→    return NextResponse.json(
192→      {
193→        success: true,
194→        meta: {
195→          version: '1.0.0',
196→          timestamp: now.toISOString(),
197→          processingTimeMs: processingTime,
198→        },
199→        data: {
200→          query: {
201→            sortBy,
202→            limit,
203→            category: category || null,
204→            healthFilter: healthFilter || null,
205→          },
206→          resultCount: formattedTools.length,
207→          tools: formattedTools,
208→          categoryDistribution: formattedCategories,
209→        },
210→      },
211→      {
212→        headers: {
213→          'Cache-Control': 'public, s-maxage=120, stale-while-revalidate=300',
214→          'X-Processing-Time': `${processingTime}ms`,
215→        },
216→      }
217→    );
218→  } catch (error) {
219→    console.error('Error fetching tool stats:', error);
220→
221→    return NextResponse.json(
222→      {
223→        success: false,
224→        error: {
225→          code: 'TOOL_STATS_ERROR',
226→          message: 'Failed to fetch tool statistics',
227→          details: error instanceof Error ? error.message : 'Unknown error',
228→        },
229→        meta: {
230→          version: '1.0.0',
231→          timestamp: new Date().toISOString(),
232→        },
233→      },
234→      { status: 500 }
235→    );
236→  }
237→}
