 1→import type { Prisma } from '@prisma/client';
 2→import { prisma } from '@tpmjs/db';
 3→import { type NextRequest, NextResponse } from 'next/server';
 4→import { API_KEY_SCOPES } from '~/lib/api-keys';
 5→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
 6→
 7→export const runtime = 'nodejs';
 8→export const dynamic = 'force-dynamic';
 9→export const maxDuration = 60;
10→
11→/**
12→ * GET /api/stats/executions/events
13→ * Query execution events with filtering and pagination.
14→ *
15→ * Query params:
16→ * - eventType: filter by event type (tool_call, agent_run, etc.)
17→ * - source: filter by source (mcp_http, agent_chat, etc.)
18→ * - toolId: filter by tool ID
19→ * - collectionId: filter by collection ID
20→ * - agentId: filter by agent ID
21→ * - limit: max results (default 50, max 100)
22→ * - cursor: ISO timestamp for cursor-based pagination (returns events before this time)
23→ */
24→export async function GET(request: NextRequest): Promise<NextResponse> {
25→  // Authenticate - require session or API key with usage:read scope
26→  const authResult = await authenticateRequest();
27→
28→  if (!authResult.authenticated) {
29→    return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
30→  }
31→
32→  if (!authResult.isSessionAuth && !hasScope(authResult, API_KEY_SCOPES.USAGE_READ)) {
33→    return NextResponse.json({ error: 'API key does not have usage:read scope' }, { status: 403 });
34→  }
35→
36→  const { searchParams } = new URL(request.url);
37→  const eventType = searchParams.get('eventType');
38→  const source = searchParams.get('source');
39→  const toolId = searchParams.get('toolId');
40→  const collectionId = searchParams.get('collectionId');
41→  const agentId = searchParams.get('agentId');
42→  const cursor = searchParams.get('cursor');
43→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
44→
45→  try {
46→    const where: Prisma.ExecutionEventWhereInput = {
47→      // Scope to the authenticated user's events
48→      userId: authResult.userId ?? undefined,
49→    };
50→
51→    if (eventType) where.eventType = eventType;
52→    if (source) where.source = source;
53→    if (toolId) where.toolId = toolId;
54→    if (collectionId) where.collectionId = collectionId;
55→    if (agentId) where.agentId = agentId;
56→    if (cursor) where.createdAt = { lt: new Date(cursor) };
57→
58→    const events = await prisma.executionEvent.findMany({
59→      where,
60→      orderBy: { createdAt: 'desc' },
61→      take: limit + 1,
62→    });
63→
64→    const hasMore = events.length > limit;
65→    const paginatedEvents = hasMore ? events.slice(0, limit) : events;
66→
67→    return NextResponse.json({
68→      success: true,
69→      data: paginatedEvents,
70→      pagination: {
71→        limit,
72→        hasMore,
73→        nextCursor:
74→          hasMore && paginatedEvents.length > 0
75→            ? paginatedEvents[paginatedEvents.length - 1]!.createdAt.toISOString()
76→            : null,
77→      },
78→    });
79→  } catch (error) {
80→    console.error('[API Error] GET /api/stats/executions/events:', error);
81→    return NextResponse.json(
82→      { success: false, error: 'Failed to fetch execution events' },
83→      { status: 500 }
84→    );
85→  }
86→}
