51→/**
52→ * Clean up old execution events.
53→ * Intended to be called from a cron job.
54→ */
55→export async function cleanupOldExecutionEvents(daysToKeep = 90): Promise<number> {
56→  const cutoff = new Date();
57→  cutoff.setDate(cutoff.getDate() - daysToKeep);
58→
59→  const result = await prisma.executionEvent.deleteMany({
60→    where: { createdAt: { lt: cutoff } },
61→  });
62→
63→  return result.count;
