  1→import type { ApiUsageSummary } from '@prisma/client';
  2→import { prisma } from '@tpmjs/db';
  3→import { headers } from 'next/headers';
  4→import { type NextRequest, NextResponse } from 'next/server';
  5→import { API_KEY_SCOPES } from '~/lib/api-keys';
  6→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
  7→import { auth } from '~/lib/auth';
  8→
  9→type Period = 'hourly' | 'daily' | 'monthly';
 10→
 11→interface AggregatedSummary {
 12→  periodStart: Date;
 13→  totalRequests: number;
 14→  successRequests: number;
 15→  errorRequests: number;
 16→  totalTokensIn: number;
 17→  totalTokensOut: number;
 18→  avgLatencyMs: number;
 19→  endpointCounts: Record<string, number>;
 20→  estimatedCostCents: number;
 21→}
 22→
 23→/**
 24→ * Aggregate hourly summaries into daily or monthly periods
 25→ */
 26→function aggregateSummaries(
 27→  hourlySummaries: ApiUsageSummary[],
 28→  period: Period
 29→): AggregatedSummary[] {
 30→  if (period === 'hourly') {
 31→    return hourlySummaries.map((s) => ({
 32→      periodStart: s.periodStart,
 33→      totalRequests: s.totalRequests,
 34→      successRequests: s.successRequests,
 35→      errorRequests: s.errorRequests,
 36→      totalTokensIn: s.totalTokensIn,
 37→      totalTokensOut: s.totalTokensOut,
 38→      avgLatencyMs: s.avgLatencyMs,
 39→      endpointCounts: s.endpointCounts as Record<string, number>,
 40→      estimatedCostCents: s.estimatedCostCents,
 41→    }));
 42→  }
 43→
 44→  // Group by period
 45→  const groups = new Map<string, ApiUsageSummary[]>();
 46→
 47→  for (const summary of hourlySummaries) {
 48→    const date = new Date(summary.periodStart);
 49→    let key: string;
 50→
 51→    if (period === 'daily') {
 52→      key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}-${String(date.getUTCDate()).padStart(2, '0')}`;
 53→    } else {
 54→      // monthly
 55→      key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
 56→    }
 57→
 58→    const existing = groups.get(key) || [];
 59→    existing.push(summary);
 60→    groups.set(key, existing);
 61→  }
 62→
 63→  // Aggregate each group
 64→  const result: AggregatedSummary[] = [];
 65→
 66→  for (const [key, summaries] of groups) {
 67→    const [year, month, day] = key.split('-').map(Number) as [number, number, number | undefined];
 68→    const periodStart =
 69→      period === 'daily'
 70→        ? new Date(Date.UTC(year, month - 1, day ?? 1))
 71→        : new Date(Date.UTC(year, month - 1, 1));
 72→
 73→    const aggregated: AggregatedSummary = {
 74→      periodStart,
 75→      totalRequests: 0,
 76→      successRequests: 0,
 77→      errorRequests: 0,
 78→      totalTokensIn: 0,
 79→      totalTokensOut: 0,
 80→      avgLatencyMs: 0,
 81→      endpointCounts: {},
 82→      estimatedCostCents: 0,
 83→    };
 84→
 85→    let totalLatencyWeight = 0;
 86→
 87→    for (const s of summaries) {
 88→      aggregated.totalRequests += s.totalRequests;
 89→      aggregated.successRequests += s.successRequests;
 90→      aggregated.errorRequests += s.errorRequests;
 91→      aggregated.totalTokensIn += s.totalTokensIn;
 92→      aggregated.totalTokensOut += s.totalTokensOut;
 93→      aggregated.estimatedCostCents += s.estimatedCostCents;
 94→
 95→      // Weighted average for latency
 96→      totalLatencyWeight += s.avgLatencyMs * s.totalRequests;
 97→
 98→      // Merge endpoint counts
 99→      const counts = s.endpointCounts as Record<string, number>;
100→      for (const [endpoint, count] of Object.entries(counts)) {
101→        aggregated.endpointCounts[endpoint] = (aggregated.endpointCounts[endpoint] || 0) + count;
102→      }
103→    }
104→
105→    if (aggregated.totalRequests > 0) {
106→      aggregated.avgLatencyMs = Math.round(totalLatencyWeight / aggregated.totalRequests);
107→    }
108→
109→    result.push(aggregated);
110→  }
111→
112→  // Sort by period start
113→  result.sort((a, b) => a.periodStart.getTime() - b.periodStart.getTime());
114→
115→  return result;
116→}
117→
118→export const runtime = 'nodejs';
119→export const dynamic = 'force-dynamic';
120→
121→/**
122→ * GET /api/user/usage
123→ *
124→ * Get usage analytics for the authenticated user.
125→ * Supports both session auth and API key auth (with usage:read scope).
126→ *
127→ * Query parameters:
128→ * - period: 'hourly' | 'daily' | 'monthly' (default: 'daily')
129→ * - start: ISO date string (default: 30 days ago)
130→ * - end: ISO date string (default: now)
131→ * - apiKeyId: Optional filter by specific API key
132→ */
133→export async function GET(request: NextRequest) {
134→  try {
135→    // Try API key auth first (for programmatic access)
136→    const apiKeyAuth = await authenticateRequest();
137→
138→    let userId: string;
139→
140→    if (apiKeyAuth.authenticated) {
141→      // Check scope for API key auth
142→      if (!hasScope(apiKeyAuth, API_KEY_SCOPES.USAGE_READ)) {
143→        return NextResponse.json({ error: 'Missing required scope: usage:read' }, { status: 403 });
144→      }
145→      userId = apiKeyAuth.userId!;
146→    } else {
147→      // Fall back to session auth
148→      const session = await auth.api.getSession({ headers: await headers() });
149→      if (!session?.user?.id) {
150→        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
151→      }
152→      userId = session.user.id;
153→    }
154→
155→    // Parse query parameters
156→    const { searchParams } = new URL(request.url);
157→    const period = (searchParams.get('period') || 'daily') as 'hourly' | 'daily' | 'monthly';
158→    const apiKeyId = searchParams.get('apiKeyId');
159→
160→    // Parse date range
161→    const now = new Date();
162→    const defaultStart = new Date();
163→    defaultStart.setDate(defaultStart.getDate() - 30);
164→
165→    const start = searchParams.get('start') ? new Date(searchParams.get('start')!) : defaultStart;
166→    const end = searchParams.get('end') ? new Date(searchParams.get('end')!) : now;
167→
168→    // Validate dates
169→    if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) {
170→      return NextResponse.json({ error: 'Invalid date format' }, { status: 400 });
171→    }
172→
173→    if (start >= end) {
174→      return NextResponse.json({ error: 'Start date must be before end date' }, { status: 400 });
175→    }
176→
177→    // Validate period
178→    if (!['hourly', 'daily', 'monthly'].includes(period)) {
179→      return NextResponse.json(
180→        { error: 'Invalid period. Use: hourly, daily, monthly' },
181→        { status: 400 }
182→      );
183→    }
184→
185→    // If apiKeyId is specified, verify ownership
186→    if (apiKeyId) {
187→      const key = await prisma.tpmjsApiKey.findFirst({
188→        where: { id: apiKeyId, userId },
189→      });
190→      if (!key) {
191→        return NextResponse.json({ error: 'API key not found' }, { status: 404 });
192→      }
193→    }
194→
195→    // Fetch hourly summaries (we always store hourly, then aggregate for daily/monthly)
196→    const hourlySummaries = await prisma.apiUsageSummary.findMany({
197→      where: {
198→        userId,
199→        periodType: 'hourly',
200→        periodStart: {
201→          gte: start,
202→          lte: end,
203→        },
204→        ...(apiKeyId ? { apiKeyId } : {}),
205→      },
206→      orderBy: { periodStart: 'asc' },
207→    });
208→
209→    // Aggregate into requested period
210→    const summaries = aggregateSummaries(hourlySummaries, period);
211→
212→    // Calculate totals
213→    const totals = summaries.reduce(
214→      (acc, summary) => ({
215→        totalRequests: acc.totalRequests + summary.totalRequests,
216→        successRequests: acc.successRequests + summary.successRequests,
217→        errorRequests: acc.errorRequests + summary.errorRequests,
218→        totalTokensIn: acc.totalTokensIn + summary.totalTokensIn,
219→        totalTokensOut: acc.totalTokensOut + summary.totalTokensOut,
220→        estimatedCostCents: acc.estimatedCostCents + summary.estimatedCostCents,
221→      }),
222→      {
223→        totalRequests: 0,
224→        successRequests: 0,
225→        errorRequests: 0,
226→        totalTokensIn: 0,
227→        totalTokensOut: 0,
228→        estimatedCostCents: 0,
229→      }
230→    );
231→
232→    // Aggregate endpoint counts across all summaries
233→    const endpointCounts: Record<string, number> = {};
234→    for (const summary of summaries) {
235→      const counts = summary.endpointCounts as Record<string, number>;
236→      for (const [endpoint, count] of Object.entries(counts)) {
237→        endpointCounts[endpoint] = (endpointCounts[endpoint] || 0) + count;
238→      }
239→    }
240→
241→    // Sort endpoints by count
242→    const sortedEndpoints = Object.entries(endpointCounts)
243→      .sort((a, b) => b[1] - a[1])
244→      .slice(0, 20); // Top 20
245→
246→    // Get usage by API key (if not filtering by specific key)
247→    let byApiKey: { keyPrefix: string; name: string; requests: number }[] = [];
248→    if (!apiKeyId) {
249→      const apiKeyUsage = await prisma.apiUsageSummary.groupBy({
250→        by: ['apiKeyId'],
251→        where: {
252→          userId,
253→          periodType: period,
254→          periodStart: {
255→            gte: start,
256→            lte: end,
257→          },
258→          apiKeyId: { not: null },
259→        },
260→        _sum: {
261→          totalRequests: true,
262→        },
263→      });
264→
265→      // Fetch key details
266→      const keyIds = apiKeyUsage.map((u) => u.apiKeyId).filter(Boolean) as string[];
267→      const keys = await prisma.tpmjsApiKey.findMany({
268→        where: { id: { in: keyIds } },
269→        select: { id: true, name: true, keyPrefix: true },
270→      });
271→
272→      const keyMap = new Map(keys.map((k) => [k.id, k]));
273→
274→      byApiKey = apiKeyUsage
275→        .filter((u) => u.apiKeyId && keyMap.has(u.apiKeyId))
276→        .map((u) => {
277→          const key = keyMap.get(u.apiKeyId!)!;
278→          return {
279→            keyPrefix: key.keyPrefix,
280→            name: key.name,
281→            requests: u._sum.totalRequests || 0,
282→          };
283→        })
284→        .sort((a, b) => b.requests - a.requests);
285→    }
286→
287→    // Format time series data
288→    const timeSeries = summaries.map((s) => ({
289→      periodStart: s.periodStart.toISOString(),
290→      totalRequests: s.totalRequests,
291→      successRequests: s.successRequests,
292→      errorRequests: s.errorRequests,
293→      totalTokensIn: s.totalTokensIn,
294→      totalTokensOut: s.totalTokensOut,
295→      avgLatencyMs: s.avgLatencyMs,
296→    }));
297→
298→    return NextResponse.json({
299→      success: true,
300→      data: {
301→        period,
302→        dateRange: {
303→          start: start.toISOString(),
304→          end: end.toISOString(),
305→        },
306→        summary: {
307→          ...totals,
308→          successRate:
309→            totals.totalRequests > 0
310→              ? Math.round((totals.successRequests / totals.totalRequests) * 100)
311→              : 0,
312→        },
313→        timeSeries,
314→        byEndpoint: sortedEndpoints.map(([endpoint, count]) => ({
315→          endpoint,
316→          count,
317→        })),
318→        byApiKey,
319→      },
320→    });
321→  } catch (error) {
322→    console.error('[Usage] Error fetching usage:', error);
323→    return NextResponse.json({ error: 'Failed to fetch usage data' }, { status: 500 });
324→  }
325→}
