  1→import { kv } from '@vercel/kv';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→import { env } from '~/env';
  4→
  5→/**
  6→ * Distributed rate limiter using Vercel KV (with in-memory fallback)
  7→ *
  8→ * Uses Vercel KV in production for accurate rate limiting across serverless instances.
  9→ * Falls back to in-memory store when KV is not available (development).
 10→ */
 11→
 12→interface RateLimitEntry {
 13→  timestamps: number[];
 14→}
 15→
 16→// In-memory fallback store (used when Vercel KV is not available)
 17→const memoryStore = new Map<string, RateLimitEntry>();
 18→
 19→// Check if Vercel KV is available
 20→const isKVAvailable = !!process.env.KV_REST_API_URL;
 21→
 22→// Cleanup interval for in-memory fallback
 23→const CLEANUP_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes
 24→const MAX_STORE_SIZE = 10000;
 25→let lastCleanup = Date.now();
 26→
 27→/**
 28→ * Clean up old entries from the in-memory fallback store
 29→ */
 30→function cleanupMemoryStore() {
 31→  const now = Date.now();
 32→  if (now - lastCleanup < CLEANUP_INTERVAL_MS) return;
 33→
 34→  const cutoff = now - 60 * 1000;
 35→  let removedCount = 0;
 36→
 37→  for (const [key, entry] of memoryStore.entries()) {
 38→    entry.timestamps = entry.timestamps.filter((ts) => ts > cutoff);
 39→    if (entry.timestamps.length === 0) {
 40→      memoryStore.delete(key);
 41→      removedCount++;
 42→    }
 43→  }
 44→
 45→  // Prevent unbounded growth
 46→  if (memoryStore.size > MAX_STORE_SIZE) {
 47→    const entries = Array.from(memoryStore.entries());
 48→    entries.sort((a, b) => {
 49→      const aLatest = a[1].timestamps.length > 0 ? Math.max(...a[1].timestamps) : 0;
 50→      const bLatest = b[1].timestamps.length > 0 ? Math.max(...b[1].timestamps) : 0;
 51→      return aLatest - bLatest;
 52→    });
 53→
 54→    const toRemove = entries.slice(0, Math.floor(MAX_STORE_SIZE * 0.2));
 55→    for (const [key] of toRemove) {
 56→      memoryStore.delete(key);
 57→      removedCount++;
 58→    }
 59→  }
 60→
 61→  lastCleanup = now;
 62→  if (removedCount > 0) {
 63→    console.log(`[Rate Limit] Cleaned up ${removedCount} in-memory entries`);
 64→  }
 65→}
 66→
 67→/**
 68→ * Get client identifier from request (IP address)
 69→ */
 70→export function getClientId(request: NextRequest): string {
 71→  const forwarded = request.headers.get('x-forwarded-for');
 72→  const realIp = request.headers.get('x-real-ip');
 73→
 74→  if (forwarded) {
 75→    return forwarded.split(',')[0]?.trim() || 'unknown';
 76→  }
 77→  if (realIp) {
 78→    return realIp;
 79→  }
 80→
 81→  return 'unknown';
 82→}
 83→
 84→/**
 85→ * Rate limit configuration
 86→ */
 87→export interface RateLimitConfig {
 88→  /** Maximum requests allowed in the window */
 89→  limit: number;
 90→  /** Time window in seconds */
 91→  windowSeconds: number;
 92→  /** Optional key prefix for namespacing */
 93→  prefix?: string;
 94→}
 95→
 96→/** Default rate limit: 1000 requests per minute */
 97→export const DEFAULT_RATE_LIMIT: RateLimitConfig = {
 98→  limit: 1000,
 99→  windowSeconds: 60,
100→};
101→
102→/** Strict rate limit for expensive operations: 200 requests per minute */
103→export const STRICT_RATE_LIMIT: RateLimitConfig = {
104→  limit: 200,
105→  windowSeconds: 60,
106→};
107→
108→/** AI generation rate limit: 50 requests per hour (expensive AI operations) */
109→export const AI_GENERATION_RATE_LIMIT: RateLimitConfig = {
110→  limit: 50,
111→  windowSeconds: 3600, // 1 hour
112→  prefix: 'ai-gen',
113→};
114→
115→/**
116→ * Helper to add timeout to promises
117→ */
118→function withTimeout<T>(promise: Promise<T>, timeoutMs: number): Promise<T | null> {
119→  const timeout = new Promise<null>((resolve) => setTimeout(() => resolve(null), timeoutMs));
120→  return Promise.race([promise, timeout]);
121→}
122→
123→/**
124→ * Get rate limit entry from Vercel KV (with timeout)
125→ */
126→async function getKVEntry(key: string): Promise<RateLimitEntry | null> {
127→  try {
128→    const result = await withTimeout(kv.get<RateLimitEntry>(key), 2000);
129→    return result;
130→  } catch (error) {
131→    console.error('[Rate Limit] KV get error:', error);
132→    return null;
133→  }
134→}
135→
136→/**
137→ * Set rate limit entry in Vercel KV (with timeout, fire-and-forget)
138→ */
139→async function setKVEntry(key: string, entry: RateLimitEntry, ttlSeconds: number): Promise<void> {
140→  try {
141→    // Fire and forget - don't wait for result, just timeout if slow
142→    withTimeout(kv.set(key, entry, { ex: ttlSeconds }), 2000);
143→  } catch (error) {
144→    console.error('[Rate Limit] KV set error:', error);
145→  }
146→}
147→
148→/**
149→ * Check if a request should be rate limited (async version for KV)
150→ */
151→async function checkRateLimitAsync(
152→  request: NextRequest,
153→  config: RateLimitConfig
154→): Promise<NextResponse | null> {
155→  const clientId = getClientId(request);
156→  const prefix = config.prefix || 'ratelimit';
157→  const key = `${prefix}:${clientId}`;
158→  const now = Date.now();
159→  const windowMs = config.windowSeconds * 1000;
160→  const cutoff = now - windowMs;
161→
162→  // Get or create entry from KV
163→  let entry = await getKVEntry(key);
164→  if (!entry) {
165→    entry = { timestamps: [] };
166→  }
167→
168→  // Remove timestamps outside the current window
169→  entry.timestamps = entry.timestamps.filter((ts) => ts > cutoff);
170→
171→  // Check if limit exceeded
172→  if (entry.timestamps.length >= config.limit) {
173→    const oldestInWindow = entry.timestamps[0] || now;
174→    const resetTime = oldestInWindow + windowMs;
175→    const retryAfterSeconds = Math.ceil((resetTime - now) / 1000);
176→
177→    return NextResponse.json(
178→      {
179→        success: false,
180→        error: 'Rate limit exceeded',
181→        message: `Too many requests. Please try again in ${retryAfterSeconds} seconds.`,
182→        retryAfter: retryAfterSeconds,
183→        limit: config.limit,
184→        window: config.windowSeconds,
185→      },
186→      {
187→        status: 429,
188→        headers: {
189→          'Retry-After': retryAfterSeconds.toString(),
190→          'X-RateLimit-Limit': config.limit.toString(),
191→          'X-RateLimit-Remaining': '0',
192→          'X-RateLimit-Reset': Math.ceil(resetTime / 1000).toString(),
193→        },
194→      }
195→    );
196→  }
197→
198→  // Add current timestamp and save
199→  entry.timestamps.push(now);
200→  await setKVEntry(key, entry, config.windowSeconds + 10); // TTL slightly longer than window
201→
202→  return null;
203→}
204→
205→/**
206→ * Check if a request should be rate limited (sync version for in-memory)
207→ */
208→function checkRateLimitSync(request: NextRequest, config: RateLimitConfig): NextResponse | null {
209→  cleanupMemoryStore();
210→
211→  const clientId = getClientId(request);
212→  const prefix = config.prefix || 'ratelimit';
213→  const key = `${prefix}:${clientId}`;
214→  const now = Date.now();
215→  const windowMs = config.windowSeconds * 1000;
216→  const cutoff = now - windowMs;
217→
218→  // Get or create entry
219→  let entry = memoryStore.get(key);
220→  if (!entry) {
221→    entry = { timestamps: [] };
222→    memoryStore.set(key, entry);
223→  }
224→
225→  // Remove timestamps outside the current window
226→  entry.timestamps = entry.timestamps.filter((ts) => ts > cutoff);
227→
228→  // Check if limit exceeded
229→  if (entry.timestamps.length >= config.limit) {
230→    const oldestInWindow = entry.timestamps[0] || now;
231→    const resetTime = oldestInWindow + windowMs;
232→    const retryAfterSeconds = Math.ceil((resetTime - now) / 1000);
233→
234→    return NextResponse.json(
235→      {
236→        success: false,
237→        error: 'Rate limit exceeded',
238→        message: `Too many requests. Please try again in ${retryAfterSeconds} seconds.`,
239→        retryAfter: retryAfterSeconds,
240→        limit: config.limit,
241→        window: config.windowSeconds,
242→      },
243→      {
244→        status: 429,
245→        headers: {
246→          'Retry-After': retryAfterSeconds.toString(),
247→          'X-RateLimit-Limit': config.limit.toString(),
248→          'X-RateLimit-Remaining': '0',
249→          'X-RateLimit-Reset': Math.ceil(resetTime / 1000).toString(),
250→        },
251→      }
252→    );
253→  }
254→
255→  // Add current timestamp
256→  entry.timestamps.push(now);
257→
258→  return null;
259→}
260→
261→/**
262→ * Check if a request should be rate limited
263→ *
264→ * Uses Vercel KV in production for distributed rate limiting,
265→ * falls back to in-memory store in development.
266→ *
267→ * @param request - Next.js request object
268→ * @param config - Rate limit configuration
269→ * @returns null if allowed, NextResponse with 429 if rate limited
270→ */
271→export function checkRateLimit(
272→  request: NextRequest,
273→  config: RateLimitConfig = DEFAULT_RATE_LIMIT
274→): NextResponse | null {
275→  // Skip rate limiting for cron jobs (authenticated with CRON_SECRET)
276→  const authHeader = request.headers.get('authorization');
277→  const token = authHeader?.replace('Bearer ', '');
278→  if (env.CRON_SECRET && token === env.CRON_SECRET) {
279→    return null;
280→  }
281→
282→  // Use sync in-memory check for immediate response
283→  // Note: KV would require async, but checkRateLimit is called synchronously
284→  // This is a limitation - for truly distributed rate limiting, consider
285→  // using middleware or making the rate limit check async
286→  return checkRateLimitSync(request, config);
287→}
288→
289→/**
290→ * Check if a request should be rate limited (async version)
291→ *
292→ * Use this when you can await the rate limit check for true distributed limiting.
293→ *
294→ * @param request - Next.js request object
295→ * @param config - Rate limit configuration
296→ * @returns null if allowed, NextResponse with 429 if rate limited
297→ */
298→export async function checkRateLimitDistributed(
299→  request: NextRequest,
300→  config: RateLimitConfig = DEFAULT_RATE_LIMIT
301→): Promise<NextResponse | null> {
302→  // Skip rate limiting for cron jobs
303→  const authHeader = request.headers.get('authorization');
304→  const token = authHeader?.replace('Bearer ', '');
305→  if (env.CRON_SECRET && token === env.CRON_SECRET) {
306→    return null;
307→  }
308→
309→  // Use KV if available, otherwise fall back to in-memory
310→  if (isKVAvailable) {
311→    return checkRateLimitAsync(request, config);
312→  }
313→
314→  return checkRateLimitSync(request, config);
315→}
316→
317→/**
318→ * Get current rate limit status for debugging
319→ */
320→export function getRateLimitStatus(
321→  request: NextRequest,
322→  config: RateLimitConfig = DEFAULT_RATE_LIMIT
323→) {
324→  const clientId = getClientId(request);
325→  const prefix = config.prefix || 'ratelimit';
326→  const key = `${prefix}:${clientId}`;
327→  const entry = memoryStore.get(key);
328→  const now = Date.now();
329→  const windowMs = config.windowSeconds * 1000;
330→  const cutoff = now - windowMs;
331→
332→  const recentRequests = entry?.timestamps.filter((ts) => ts > cutoff).length || 0;
333→  const remaining = Math.max(0, config.limit - recentRequests);
334→
335→  return {
336→    clientId,
337→    limit: config.limit,
338→    remaining,
339→    used: recentRequests,
340→    resetAt: new Date(now + windowMs),
341→    isDistributed: isKVAvailable,
342→  };
343→}
