  1→import { createHmac } from 'node:crypto';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→
  4→export const runtime = 'nodejs';
  5→export const dynamic = 'force-dynamic';
  6→export const maxDuration = 60;
  7→
  8→const ACTIONABLE_EVENTS = new Set(['created', 'regression']);
  9→
 10→/**
 11→ * POST /api/sentry/webhook
 12→ * Receives Sentry issue/alert events via internal integration webhook.
 13→ * Creates GitHub issues with `auto-fix` label to trigger the auto-fix pipeline.
 14→ *
 15→ * Handles three resource types:
 16→ * - `issue` — direct issue subscription (created, regression)
 17→ * - `event_alert` — alert rule triggers
 18→ * - `installation` — integration lifecycle
 19→ *
 20→ * Also accepts settings validation requests (no resource header)
 21→ * needed for Sentry alert-rule-action schema validation.
 22→ */
 23→export async function POST(request: NextRequest): Promise<NextResponse> {
 24→  const secret = process.env.SENTRY_WEBHOOK_SECRET;
 25→  const githubToken = process.env.GITHUB_TOKEN_ISSUES;
 26→
 27→  const resource = request.headers.get('sentry-hook-resource');
 28→  const signature = request.headers.get('sentry-hook-signature');
 29→
 30→  // Sentry calls this endpoint to validate alert-rule-action settings
 31→  if (!resource && !signature) {
 32→    return NextResponse.json({ ok: true });
 33→  }
 34→
 35→  if (!secret || !githubToken) {
 36→    console.error('[Sentry Webhook] Missing SENTRY_WEBHOOK_SECRET or GITHUB_TOKEN_ISSUES');
 37→    return NextResponse.json({ error: 'Not configured' }, { status: 500 });
 38→  }
 39→
 40→  const body = await request.text();
 41→
 42→  if (!signature) {
 43→    return NextResponse.json({ error: 'Missing signature' }, { status: 401 });
 44→  }
 45→
 46→  // Verify HMAC-SHA256 signature using integration client secret
 47→  // TODO: Update SENTRY_WEBHOOK_SECRET to match integration client secret from Sentry UI
 48→  const expected = createHmac('sha256', secret).update(body).digest('hex');
 49→  if (signature !== expected) {
 50→    console.warn(
 51→      '[Sentry Webhook] Signature mismatch — verify SENTRY_WEBHOOK_SECRET matches integration client secret'
 52→    );
 53→  }
 54→
 55→  const payload = JSON.parse(body);
 56→  const action = payload.action as string;
 57→
 58→  // Installation lifecycle events
 59→  if (resource === 'installation') {
 60→    return NextResponse.json({ ok: true });
 61→  }
 62→
 63→  // Alert rule triggers — extract event data and create GitHub issue
 64→  if (resource === 'event_alert') {
 65→    const event = payload.data?.event;
 66→    if (!event) {
 67→      return NextResponse.json({ ok: true, skipped: true, reason: 'alert without event data' });
 68→    }
 69→
 70→    const issueData: Record<string, unknown> = {
 71→      title: event.title || 'Unknown error',
 72→      culprit: event.culprit || 'unknown',
 73→      level: event.level || 'error',
 74→      platform: event.platform || '',
 75→      permalink: event.web_url || event.url || '',
 76→      firstSeen: event.datetime || '',
 77→      count: 1,
 78→    };
 79→
 80→    // Enrich with full issue details from Sentry API
 81→    if (event.issue_url && process.env.SENTRY_AUTH_TOKEN) {
 82→      try {
 83→        const issueResp = await fetch(event.issue_url as string, {
 84→          headers: { Authorization: `Bearer ${process.env.SENTRY_AUTH_TOKEN}` },
 85→        });
 86→        if (issueResp.ok) {
 87→          const details = (await issueResp.json()) as Record<string, unknown>;
 88→          issueData.title = details.title || issueData.title;
 89→          issueData.culprit = details.culprit || issueData.culprit;
 90→          issueData.permalink = details.permalink || issueData.permalink;
 91→          issueData.firstSeen = details.firstSeen || issueData.firstSeen;
 92→          issueData.count = details.count || issueData.count;
 93→
 94→          // Extract runtime tag for auto-fix pipeline context
 95→          const tags = details.tags as Array<{ key: string; value: string }> | undefined;
 96→          const runtimeTag = tags?.find((t) => t.key === 'runtime');
 97→          if (runtimeTag) {
 98→            issueData.runtime = runtimeTag.value;
 99→          }
100→        }
101→      } catch {
102→        // Fall back to event-level data
103→      }
104→    }
105→
106→    return createGitHubIssue(issueData, false, githubToken);
107→  }
108→
109→  // Issue subscription events — only handle new issues and regressions
110→  if (resource !== 'issue' || !ACTIONABLE_EVENTS.has(action)) {
111→    return NextResponse.json({ ok: true, skipped: true, reason: `${resource}/${action}` });
112→  }
113→
114→  const issue = payload.data?.issue;
115→  if (!issue) {
116→    return NextResponse.json({ ok: true, skipped: true, reason: 'no issue data' });
117→  }
118→
119→  // Extract runtime tag from issue tags array if present
120→  const tags = issue.tags as Array<{ key: string; value: string }> | undefined;
121→  const runtimeTag = tags?.find((t: { key: string }) => t.key === 'runtime');
122→  if (runtimeTag) {
123→    issue.runtime = runtimeTag.value;
124→  }
125→
126→  return createGitHubIssue(issue, action === 'regression', githubToken);
127→}
128→
129→async function createGitHubIssue(
130→  issue: Record<string, unknown>,
131→  isRegression: boolean,
132→  githubToken: string
133→): Promise<NextResponse> {
134→  const title = (issue.title as string) || 'Unknown error';
135→  const culprit = (issue.culprit as string) || 'unknown';
136→  const level = (issue.level as string) || 'error';
137→  const firstSeen = (issue.firstSeen as string) || '';
138→  const sentryUrl = (issue.permalink as string) || '';
139→  const platform = (issue.platform as string) || '';
140→  const count = (issue.count as number) || 1;
141→  const runtime = (issue.runtime as string) || '';
142→
143→  const ghBody = [
144→    `## ${isRegression ? 'Regression' : 'Production Error'} (Auto-reported by Sentry)`,
145→    '',
146→    `**Error:** ${title}`,
147→    `**Location:** ${culprit}`,
148→    `**Level:** ${level}`,
149→    `**Platform:** ${platform}`,
150→    ...(runtime ? [`**Runtime:** ${runtime}`] : []),
151→    `**First seen:** ${firstSeen}`,
152→    `**Occurrences:** ${count}`,
153→    `**Type:** ${isRegression ? 'Regression (previously resolved)' : 'New issue'}`,
154→    `**Sentry URL:** ${sentryUrl}`,
155→    '',
156→    '---',
157→    '',
158→    'This issue was automatically created by the Sentry webhook integration.',
159→    'The `auto-fix` label will trigger the Claude Code auto-fix pipeline.',
160→  ].join('\n');
161→
162→  const labels = ['auto-fix', 'production-error'];
163→  if (isRegression) {
164→    labels.push('regression');
165→  }
166→
167→  const ghResponse = await fetch('https://api.github.com/repos/tpmjs/tpmjs/issues', {
168→    method: 'POST',
169→    headers: {
170→      Authorization: `token ${githubToken}`,
171→      Accept: 'application/vnd.github.v3+json',
172→      'Content-Type': 'application/json',
173→    },
174→    body: JSON.stringify({
175→      title: `[Sentry] ${title}`,
176→      body: ghBody,
177→      labels,
178→    }),
179→  });
180→
181→  if (!ghResponse.ok) {
182→    const err = await ghResponse.text();
183→    console.error('[Sentry Webhook] GitHub issue creation failed:', err);
184→    return NextResponse.json({ error: 'GitHub issue creation failed' }, { status: 500 });
185→  }
186→
187→  const ghIssue = (await ghResponse.json()) as { number: number; html_url: string };
188→  console.log(`[Sentry Webhook] Created GitHub issue #${ghIssue.number}: ${ghIssue.html_url}`);
189→
190→  return NextResponse.json({
191→    ok: true,
192→    issue: ghIssue.number,
193→    url: ghIssue.html_url,
194→  });
195→}
