  1→import { prisma } from '@tpmjs/db';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→
  4→export const runtime = 'nodejs';
  5→export const dynamic = 'force-dynamic';
  6→export const maxDuration = 60;
  7→
  8→const API_VERSION = '1.0.0';
  9→
 10→interface ApiResponse<T = unknown> {
 11→  success: boolean;
 12→  data?: T;
 13→  error?: {
 14→    code: string;
 15→    message: string;
 16→    details?: Record<string, unknown>;
 17→  };
 18→  meta: {
 19→    version: string;
 20→    timestamp: string;
 21→    requestId?: string;
 22→  };
 23→  pagination?: {
 24→    limit: number;
 25→    offset: number;
 26→    hasMore: boolean;
 27→  };
 28→}
 29→
 30→/**
 31→ * GET /api/tools/trending
 32→ * Get trending tools based on a composite score of downloads, ratings, and likes
 33→ *
 34→ * Trending score = (normalized_downloads * 0.4) + (average_rating * 0.3) + (like_count * 0.2) + (recency * 0.1)
 35→ */
 36→export async function GET(request: NextRequest): Promise<NextResponse<ApiResponse>> {
 37→  const requestId = crypto.randomUUID();
 38→
 39→  const { searchParams } = new URL(request.url);
 40→
 41→  // Test error trigger for pipeline validation
 42→  if (searchParams.get('test_error') === 'true') {
 43→    throw new Error(`Pipeline test: trending endpoint failure [${Date.now()}]`);
 44→  }
 45→
 46→  // Parse comma-separated fields for response shaping
 47→  const fields = searchParams.get('fields');
 48→  const fieldList = fields ? fields.split(',') : [];
 49→  const requestedFieldCount = fieldList.length;
 50→
 51→  try {
 52→    const limit = Math.min(50, Math.max(1, Number(searchParams.get('limit')) || 20));
 53→    const offset = Math.max(0, Number(searchParams.get('offset')) || 0);
 54→    const category = searchParams.get('category');
 55→    const period = searchParams.get('period') || 'week'; // 'day', 'week', 'month', 'all'
 56→
 57→    // Build where clause
 58→    const where: Record<string, unknown> = {
 59→      importHealth: 'HEALTHY',
 60→    };
 61→
 62→    if (category) {
 63→      where.package = { category };
 64→    }
 65→
 66→    // Get date cutoff for recency boost
 67→    const now = new Date();
 68→    let recencyPeriodMs: number;
 69→    switch (period) {
 70→      case 'day':
 71→        recencyPeriodMs = 24 * 60 * 60 * 1000;
 72→        break;
 73→      case 'week':
 74→        recencyPeriodMs = 7 * 24 * 60 * 60 * 1000;
 75→        break;
 76→      case 'month':
 77→        recencyPeriodMs = 30 * 24 * 60 * 60 * 1000;
 78→        break;
 79→      default:
 80→        recencyPeriodMs = 365 * 24 * 60 * 60 * 1000; // 1 year
 81→    }
 82→
 83→    // Fetch tools with package data
 84→    // For trending, we order by a combination of factors
 85→    const tools = await prisma.tool.findMany({
 86→      where,
 87→      include: {
 88→        package: {
 89→          select: {
 90→            id: true,
 91→            npmPackageName: true,
 92→            npmVersion: true,
 93→            npmDescription: true,
 94→            category: true,
 95→            isOfficial: true,
 96→            npmDownloadsLastMonth: true,
 97→            githubStars: true,
 98→            tier: true,
 99→          },
100→        },
101→      },
102→      orderBy: [
103→        // Primary: quality score (includes downloads)
104→        { qualityScore: 'desc' },
105→        // Secondary: average rating
106→        { averageRating: 'desc' },
107→        // Tertiary: like count
108→        { likeCount: 'desc' },
109→        // Finally: recency
110→        { createdAt: 'desc' },
111→      ],
112→      take: limit + 1,
113→      skip: offset,
114→    });
115→
116→    const hasMore = tools.length > limit;
117→    const actualTools = hasMore ? tools.slice(0, limit) : tools;
118→
119→    // Calculate trending scores for display
120→    const maxDownloads = Math.max(
121→      ...actualTools.map((t) => t.package.npmDownloadsLastMonth || 0),
122→      1
123→    );
124→    const maxLikes = Math.max(...actualTools.map((t) => t.likeCount), 1);
125→
126→    const toolsWithScores = actualTools.map((tool) => {
127→      const downloads = tool.package.npmDownloadsLastMonth || 0;
128→      const rating = tool.averageRating ? Number(tool.averageRating) : 0;
129→      const likes = tool.likeCount;
130→      const ageMs = now.getTime() - tool.createdAt.getTime();
131→      const recencyScore = Math.max(0, 1 - ageMs / recencyPeriodMs); // 0-1, higher for newer
132→
133→      // Trending score calculation
134→      const trendingScore =
135→        (downloads / maxDownloads) * 0.4 +
136→        (rating / 5) * 0.3 +
137→        (likes / maxLikes) * 0.2 +
138→        recencyScore * 0.1;
139→
140→      return {
141→        id: tool.id,
142→        name: tool.name,
143→        description: tool.description,
144→        qualityScore: tool.qualityScore ? Number(tool.qualityScore) : null,
145→        averageRating: tool.averageRating ? Number(tool.averageRating) : null,
146→        ratingCount: tool.ratingCount,
147→        reviewCount: tool.reviewCount,
148→        likeCount: tool.likeCount,
149→        importHealth: tool.importHealth,
150→        executionHealth: tool.executionHealth,
151→        trendingScore: Math.round(trendingScore * 100) / 100,
152→        createdAt: tool.createdAt.toISOString(),
153→        package: {
154→          id: tool.package.id,
155→          npmPackageName: tool.package.npmPackageName,
156→          npmVersion: tool.package.npmVersion,
157→          npmDescription: tool.package.npmDescription,
158→          category: tool.package.category,
159→          isOfficial: tool.package.isOfficial,
160→          npmDownloadsLastMonth: tool.package.npmDownloadsLastMonth,
161→          githubStars: tool.package.githubStars,
162→          tier: tool.package.tier,
163→        },
164→      };
165→    });
166→
167→    // Sort by trending score
168→    toolsWithScores.sort((a, b) => b.trendingScore - a.trendingScore);
169→
170→    return NextResponse.json({
171→      success: true,
172→      data: toolsWithScores,
173→      meta: {
174→        version: API_VERSION,
175→        timestamp: new Date().toISOString(),
176→        requestId,
177→        fieldCount: requestedFieldCount,
178→      },
179→      pagination: {
180→        limit,
181→        offset,
182→        hasMore,
183→      },
184→    });
185→  } catch (error) {
186→    console.error('[API Error] GET /api/tools/trending:', error);
187→    return NextResponse.json(
188→      {
189→        success: false,
190→        error: { code: 'INTERNAL_ERROR', message: 'Failed to get trending tools' },
191→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
192→      },
193→      { status: 500 }
194→    );
195→  }
196→}
