 1→import { prisma } from '@tpmjs/db';
 2→import { type NextRequest, NextResponse } from 'next/server';
 3→import { getClientId } from '~/lib/rate-limit';
 4→
 5→export const runtime = 'nodejs';
 6→export const dynamic = 'force-dynamic';
 7→export const maxDuration = 10;
 8→
 9→const VALID_ENTITY_TYPES = ['tool', 'collection', 'agent'] as const;
10→
11→// Simple in-memory dedup: 1 view per entity per IP per hour
12→const recentViews = new Map<string, number>();
13→
14→// Clean up every 10 minutes
15→setInterval(() => {
16→  const now = Date.now();
17→  for (const [key, timestamp] of recentViews) {
18→    if (now - timestamp > 3600_000) {
19→      recentViews.delete(key);
20→    }
21→  }
22→  // Prevent unbounded growth
23→  if (recentViews.size > 50_000) {
24→    recentViews.clear();
25→  }
26→}, 600_000);
27→
28→/**
29→ * POST /api/track/view
30→ * Fire-and-forget view tracking. Upserts into PageView with daily bucket.
31→ */
32→export async function POST(request: NextRequest) {
33→  try {
34→    const body = await request.json();
35→    const { entityType, entityId } = body;
36→
37→    // Validate input
38→    if (!entityType || !entityId) {
39→      return NextResponse.json({ error: 'Missing entityType or entityId' }, { status: 400 });
40→    }
41→
42→    if (!VALID_ENTITY_TYPES.includes(entityType)) {
43→      return NextResponse.json({ error: 'Invalid entityType' }, { status: 400 });
44→    }
45→
46→    // Rate-limit: 1 view per entity per IP per hour
47→    const clientId = getClientId(request);
48→    const dedupKey = `${clientId}:${entityType}:${entityId}`;
49→    const lastView = recentViews.get(dedupKey);
50→
51→    if (lastView && Date.now() - lastView < 3600_000) {
52→      return NextResponse.json({ ok: true, deduped: true });
53→    }
54→
55→    recentViews.set(dedupKey, Date.now());
56→
57→    // Today's date bucket (midnight UTC)
58→    const today = new Date();
59→    today.setUTCHours(0, 0, 0, 0);
60→
61→    // Upsert page view (fire-and-forget style, don't await in production but we need to for correctness)
62→    await prisma.pageView.upsert({
63→      where: {
64→        entityType_entityId_date: {
65→          entityType,
66→          entityId,
67→          date: today,
68→        },
69→      },
70→      create: {
71→        entityType,
72→        entityId,
73→        date: today,
74→        viewCount: 1,
75→      },
76→      update: {
77→        viewCount: { increment: 1 },
78→      },
79→    });
80→
81→    return NextResponse.json({ ok: true });
82→  } catch (error) {
83→    // Silently fail - view tracking should never break the user experience
84→    console.error('[track/view] Error:', error);
85→    return NextResponse.json({ ok: true });
86→  }
87→}
