  3→/**
  4→ * Usage tracking for API keys
  5→ *
  6→ * Tracks individual requests and maintains hourly summaries.
  7→ * All tracking is non-blocking to avoid impacting request latency.
  8→ */
  9→
 10→/**
 11→ * Event data for usage tracking
 12→ */
 13→export interface UsageEvent {
 14→  /** API key ID (required for API key auth) */
 15→  apiKeyId?: string;
 16→  /** User ID (required) */
 17→  userId: string;
 18→  /** Request endpoint (e.g., "/api/mcp/user/collection/streamable-http") */
 19→  endpoint: string;
 20→  /** HTTP method */
 21→  method: string;
 22→  /** HTTP status code */
 23→  statusCode: number;
 24→  /** Request latency in milliseconds */
 25→  latencyMs: number;
 26→  /** Resource type (e.g., "mcp", "agent", "bridge", "collection") */
 27→  resourceType?: string;
 28→  /** Resource ID (e.g., collection ID, agent ID) */
 29→  resourceId?: string;
 30→  /** Input tokens (for LLM requests) */
 31→  tokensIn?: number;
 32→  /** Output tokens (for LLM requests) */
 33→  tokensOut?: number;
 34→  /** Model used (for LLM requests) */
 35→  model?: string;
 36→  /** Error code if request failed */
 37→  errorCode?: string;
 38→  /** Error message if request failed */
 39→  errorMessage?: string;
 40→  /** User agent string */
 41→  userAgent?: string | null;
 42→  /** Client IP address */
 43→  ipAddress?: string | null;
 44→}
 45→
 46→/**
 47→ * Track API usage (fire and forget - non-blocking)
 48→ *
 49→ * This function returns immediately and tracks usage in the background.
 50→ * Errors are logged but don't affect the calling code.
 51→ *
 52→ * @param event - Usage event data
 53→ *
 54→ * @example
 55→ * trackUsage({
 56→ *   apiKeyId: auth.apiKeyId,
 57→ *   userId: auth.userId,
 58→ *   endpoint: '/api/mcp/...',
 59→ *   method: 'POST',
 60→ *   statusCode: 200,
 61→ *   latencyMs: 150,
 62→ *   resourceType: 'mcp',
 63→ *   resourceId: collectionId,
 64→ * });
 65→ */
 66→export function trackUsage(event: UsageEvent): void {
 67→  // Fire and forget - don't await
 68→  trackUsageAsync(event).catch((error) => {
 69→    console.error('[Usage Tracking] Error tracking usage:', error);
 70→  });
 71→}
 72→
 73→/**
 74→ * Async implementation of usage tracking
 75→ */
 76→async function trackUsageAsync(event: UsageEvent): Promise<void> {
 77→  const now = new Date();
 78→
 79→  // 1. Create individual record (only if authenticated via API key)
 80→  if (event.apiKeyId) {
 81→    await prisma.apiUsageRecord.create({
 82→      data: {
 83→        apiKeyId: event.apiKeyId,
 84→        endpoint: event.endpoint,
 85→        method: event.method,
 86→        statusCode: event.statusCode,
 87→        latencyMs: event.latencyMs,
 88→        resourceType: event.resourceType,
 89→        resourceId: event.resourceId,
 90→        tokensIn: event.tokensIn,
 91→        tokensOut: event.tokensOut,
 92→        model: event.model,
 93→        errorCode: event.errorCode,
 94→        errorMessage: event.errorMessage,
 95→        userAgent: event.userAgent?.substring(0, 500), // Truncate to fit DB column
 96→        ipAddress: event.ipAddress?.substring(0, 45),
 97→      },
 98→    });
 99→  }
100→
101→  // 2. Update hourly summary (upsert)
102→  const hourStart = new Date(now);
103→  hourStart.setMinutes(0, 0, 0);
104→
105→  const isSuccess = event.statusCode < 400;
106→  const isError = event.statusCode >= 400;
107→
108→  // Create a normalized endpoint for summary (remove dynamic segments)
109→  const normalizedEndpoint = normalizeEndpoint(event.endpoint);
110→
111→  await prisma.apiUsageSummary.upsert({
112→    where: {
113→      userId_apiKeyId_periodType_periodStart: {
114→        userId: event.userId,
115→        apiKeyId: event.apiKeyId || '',
116→        periodType: 'hourly',
117→        periodStart: hourStart,
118→      },
119→    },
120→    create: {
121→      userId: event.userId,
122→      apiKeyId: event.apiKeyId,
123→      periodType: 'hourly',
124→      periodStart: hourStart,
125→      totalRequests: 1,
126→      successRequests: isSuccess ? 1 : 0,
127→      errorRequests: isError ? 1 : 0,
128→      endpointCounts: { [normalizedEndpoint]: 1 },
129→      totalTokensIn: event.tokensIn || 0,
130→      totalTokensOut: event.tokensOut || 0,
131→      avgLatencyMs: event.latencyMs,
132→    },
133→    update: {
134→      totalRequests: { increment: 1 },
135→      successRequests: { increment: isSuccess ? 1 : 0 },
136→      errorRequests: { increment: isError ? 1 : 0 },
137→      totalTokensIn: { increment: event.tokensIn || 0 },
138→      totalTokensOut: { increment: event.tokensOut || 0 },
139→      // Note: For proper running average, we'd need to fetch current values
140→      // For now, we'll update avgLatencyMs via a background job
141→    },
142→  });
143→
144→  // Update endpoint counts separately (JSON increment isn't supported directly)
145→  // We do this via raw SQL for efficiency
146→  try {
147→    await prisma.$executeRaw`
148→      UPDATE api_usage_summaries
149→      SET endpoint_counts = jsonb_set(
150→        COALESCE(endpoint_counts, '{}'::jsonb),
151→        ${`{${normalizedEndpoint}}`}::text[],
152→        (COALESCE((endpoint_counts->${normalizedEndpoint})::int, 0) + 1)::text::jsonb
153→      )
154→      WHERE user_id = ${event.userId}
155→        AND COALESCE(api_key_id, '') = ${event.apiKeyId || ''}
156→        AND period_type = 'hourly'
157→        AND period_start = ${hourStart}
158→    `;
159→  } catch {
160→    // Ignore JSON update errors - the main counts are still accurate
161→  }
162→}
163→
164→/**
165→ * Normalize endpoint for aggregation
166→ *
167→ * Replaces dynamic segments (IDs, slugs) with placeholders.
168→ * This groups similar requests together in summaries.
169→ *
170→ * @param endpoint - Raw endpoint path
171→ * @returns Normalized endpoint
172→ */
173→function normalizeEndpoint(endpoint: string): string {
174→  return (
175→    (endpoint.split('?')[0] ?? endpoint)
176→      // Replace UUIDs and CUIDs with placeholder
177→      .replace(/\/[a-z0-9]{20,}/gi, '/:id')
178→      // Replace numeric IDs
179→      .replace(/\/\d+/g, '/:id')
180→      // Limit length
181→      .substring(0, 100)
182→  );
183→}
184→
185→/**
186→ * Create a usage tracker wrapper for route handlers
187→ *
188→ * This makes it easy to track usage in route handlers.
189→ *
190→ * @param userId - User ID
191→ * @param apiKeyId - Optional API key ID
192→ * @returns Object with track method and helper functions
193→ *
194→ * @example
195→ * const tracker = createUsageTracker(auth.userId, auth.apiKeyId);
196→ * tracker.track({
197→ *   endpoint: '/api/mcp/...',
198→ *   method: 'POST',
199→ *   statusCode: 200,
200→ *   latencyMs: 150,
201→ * });
202→ */
203→export function createUsageTracker(userId: string, apiKeyId?: string) {
204→  const startTime = Date.now();
205→
206→  return {
207→    /**
208→     * Track a usage event
209→     */
210→    track(
211→      event: Omit<UsageEvent, 'userId' | 'apiKeyId'> & {
212→        userId?: string;
213→        apiKeyId?: string;
214→      }
215→    ) {
216→      trackUsage({
217→        ...event,
218→        userId: event.userId || userId,
219→        apiKeyId: event.apiKeyId || apiKeyId,
220→      });
221→    },
222→
223→    /**
224→     * Track completion with automatic latency calculation
225→     */
226→    trackCompletion(
227→      event: Omit<UsageEvent, 'userId' | 'apiKeyId' | 'latencyMs'> & {
228→        userId?: string;
229→        apiKeyId?: string;
230→        latencyMs?: number;
231→      }
232→    ) {
233→      trackUsage({
234→        ...event,
235→        userId: event.userId || userId,
236→        apiKeyId: event.apiKeyId || apiKeyId,
237→        latencyMs: event.latencyMs || Date.now() - startTime,
238→      });
239→    },
240→
241→    /**
242→     * Get elapsed time since tracker creation
243→     */
244→    getElapsedMs() {
245→      return Date.now() - startTime;
246→    },
247→  };
248→}
