250→/**
251→ * Cleanup old usage records (called by cron job)
252→ *
253→ * Deletes individual records older than 30 days.
254→ * Summaries are kept for longer-term analytics.
255→ *
256→ * @param daysToKeep - Number of days to keep records (default 30)
257→ * @returns Number of records deleted
258→ */
259→export async function cleanupOldUsageRecords(daysToKeep = 30): Promise<number> {
260→  const cutoff = new Date();
