  9→/**
 10→ * POST /api/sync/cleanup-activity
 11→ * Delete activity records older than 90 days
 12→ *
 13→ * This endpoint is called by Vercel Cron (daily at 3 AM UTC)
 14→ * Requires Authorization: Bearer <CRON_SECRET>
 15→ */
 16→export async function POST(request: NextRequest) {
 17→  // Verify cron secret for security
 18→  const authHeader = request.headers.get('authorization');
 19→  const token = authHeader?.replace('Bearer ', '');
 20→
 21→  if (env.CRON_SECRET && token !== env.CRON_SECRET) {
 22→    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 23→  }
 24→
 25→  const startTime = Date.now();
 26→
 27→  try {
 28→    // Calculate the cutoff date (90 days ago)
 29→    const cutoffDate = new Date();
 30→    cutoffDate.setDate(cutoffDate.getDate() - 90);
 31→
 32→    // Delete activities older than 90 days
 33→    const result = await prisma.userActivity.deleteMany({
 34→      where: {
 35→        createdAt: {
 36→          lt: cutoffDate,
 37→        },
 38→      },
 39→    });
 40→
 41→    const durationMs = Date.now() - startTime;
 42→
 43→    // Log the cleanup to syncLog
 44→    await prisma.syncLog.create({
 45→      data: {
 46→        source: 'cleanup-activity',
 47→        status: 'success',
 48→        processed: result.count,
 49→        skipped: 0,
 50→        errors: 0,
 51→        message: `Deleted ${result.count} activities older than 90 days`,
 52→        metadata: {
 53→          durationMs,
 54→          cutoffDate: cutoffDate.toISOString(),
 55→        },
 56→      },
 57→    });
 58→
 59→    // Update checkpoint with last run timestamp
 60→    await prisma.syncCheckpoint.upsert({
 61→      where: { source: 'cleanup-activity' },
 62→      create: {
 63→        source: 'cleanup-activity',
 64→        checkpoint: {
 65→          lastRun: new Date().toISOString(),
 66→          deletedCount: result.count,
 67→        },
 68→      },
 69→      update: {
 70→        checkpoint: {
 71→          lastRun: new Date().toISOString(),
 72→          deletedCount: result.count,
 73→        },
 74→      },
 75→    });
 76→
 77→    return NextResponse.json({
 78→      success: true,
 79→      data: {
 80→        deleted: result.count,
 81→        cutoffDate: cutoffDate.toISOString(),
 82→        durationMs,
 83→      },
 84→    });
 85→  } catch (error) {
 86→    const durationMs = Date.now() - startTime;
 87→    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
 88→
 89→    // Log the error to syncLog
 90→    await prisma.syncLog
 91→      .create({
 92→        data: {
 93→          source: 'cleanup-activity',
 94→          status: 'error',
 95→          processed: 0,
 96→          skipped: 0,
 97→          errors: 1,
 98→          message: errorMessage,
 99→          metadata: { durationMs },
100→        },
101→      })
102→      .catch(console.error);
103→
104→    console.error('[Cleanup Activity Error]', error);
105→
106→    return NextResponse.json(
107→      {
108→        success: false,
109→        error: errorMessage,
110→        data: { durationMs },
111→      },
112→      { status: 500 }
113→    );
114→  }
115→}
