 1→import { prisma } from '@tpmjs/db';
 2→import { type NextRequest, NextResponse } from 'next/server';
 3→
 4→export const runtime = 'nodejs';
 5→export const dynamic = 'force-dynamic';
 6→export const maxDuration = 300;
 7→
 8→/**
 9→ * POST /api/sync/view-rollup
10→ * Daily cron: aggregates PageView counts into denormalized viewCount fields
11→ * on Tool, Collection, and Agent models.
12→ */
13→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: cron handler with sequential entity type processing
14→export async function POST(request: NextRequest) {
15→  const startTime = Date.now();
16→
17→  // Verify cron secret
18→  const authHeader = request.headers.get('authorization');
19→  const cronSecret = process.env.CRON_SECRET;
20→
21→  if (cronSecret && authHeader !== `Bearer ${cronSecret}`) {
22→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
23→  }
24→
25→  try {
26→    // Aggregate views by entity type and entity ID (all-time sum)
27→    const entityTypes = ['tool', 'collection', 'agent'] as const;
28→    let totalUpdated = 0;
29→
30→    for (const entityType of entityTypes) {
31→      // Get aggregated view counts per entity
32→      const viewCounts = await prisma.pageView.groupBy({
33→        by: ['entityId'],
34→        where: { entityType },
35→        _sum: { viewCount: true },
36→      });
37→
38→      // Update denormalized viewCount on each entity
39→      for (const vc of viewCounts) {
40→        const totalViews = vc._sum.viewCount || 0;
41→        if (totalViews === 0) continue;
42→
43→        try {
44→          if (entityType === 'tool') {
45→            await prisma.tool.update({
46→              where: { id: vc.entityId },
47→              data: { viewCount: totalViews },
48→            });
49→          } else if (entityType === 'collection') {
50→            await prisma.collection.update({
51→              where: { id: vc.entityId },
52→              data: { viewCount: totalViews },
53→            });
54→          } else if (entityType === 'agent') {
55→            await prisma.agent.update({
56→              where: { id: vc.entityId },
57→              data: { viewCount: totalViews },
58→            });
59→          }
60→          totalUpdated++;
61→        } catch {
62→          // Entity may have been deleted - skip silently
63→        }
64→      }
65→    }
66→
67→    const durationMs = Date.now() - startTime;
68→
69→    return NextResponse.json({
70→      success: true,
71→      data: {
72→        totalUpdated,
73→        durationMs,
74→      },
75→    });
76→  } catch (error) {
77→    console.error('[sync/view-rollup] Error:', error);
78→    return NextResponse.json(
79→      {
80→        success: false,
81→        error: error instanceof Error ? error.message : 'Unknown error',
82→      },
83→      { status: 500 }
84→    );
85→  }
86→}
