  9→// BM25 parameters
 10→const k1 = 1.5; // term frequency saturation parameter
 11→const b = 0.75; // length normalization parameter
 12→
 13→// Split camelCase and PascalCase into words
 14→function splitCamelCase(text: string): string {
 15→  return text
 16→    .replace(/([a-z])([A-Z])/g, '$1 $2') // camelCase -> camel Case
 17→    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2'); // XMLParser -> XML Parser
 18→}
 19→
 20→// Tokenize text into words (handles camelCase)
 21→function tokenize(text: string): string[] {
 22→  return splitCamelCase(text)
 23→    .toLowerCase()
 24→    .replace(/[^\w\s]/g, ' ')
 25→    .split(/\s+/)
 26→    .filter((t) => t.length > 0);
 27→}
 28→
 29→// Check for exact tool name match (case-insensitive)
 30→function hasExactNameMatch(query: string, toolName: string): boolean {
 31→  const queryLower = query.toLowerCase();
 32→  const nameLower = toolName.toLowerCase();
 33→  return queryLower.includes(nameLower) || nameLower.includes(queryLower);
 34→}
 35→
 36→// Check for package name match (case-insensitive)
 37→function hasPackageNameMatch(query: string, packageName: string): boolean {
 38→  const queryLower = query.toLowerCase();
 39→  const packageLower = packageName.toLowerCase();
 40→  // Check if query contains package name or package name contains query
 41→  // Also handle partial matches like "@tpmjs/tools-" matching "@tpmjs/tools-unsandbox"
 42→  return queryLower.includes(packageLower) || packageLower.includes(queryLower);
 43→}
 44→
 45→// Calculate term frequency
 46→function termFrequency(term: string, tokens: string[]): number {
 47→  return tokens.filter((t) => t === term).length;
 48→}
 49→
 50→// Calculate BM25 score
 51→function calculateBM25(
 52→  query: string,
 53→  document: string,
 54→  avgDocLength: number,
 55→  totalDocs: number,
 56→  docFrequencies: Map<string, number>
 57→): number {
 58→  const queryTokens = tokenize(query);
 59→  const docTokens = tokenize(document);
 60→  const docLength = docTokens.length;
 61→
 62→  let score = 0;
 63→
 64→  for (const term of queryTokens) {
 65→    const tf = termFrequency(term, docTokens);
 66→    if (tf === 0) continue;
 67→
 68→    // IDF calculation
 69→    const docFreq = docFrequencies.get(term) || 0;
 70→    const idf = Math.log((totalDocs - docFreq + 0.5) / (docFreq + 0.5) + 1);
 71→
 72→    // BM25 formula
 73→    const numerator = tf * (k1 + 1);
 74→    const denominator = tf + k1 * (1 - b + b * (docLength / avgDocLength));
 75→
 76→    score += idf * (numerator / denominator);
 77→  }
 78→
 79→  return score;
 80→}
 81→
 82→export async function GET(request: NextRequest) {
 83→  console.log('🔎 [SEARCH API] Request received');
 84→
 85→  // Check rate limit (stricter limit for expensive search operations)
 86→  const rateLimitResponse = checkRateLimit(request, STRICT_RATE_LIMIT);
 87→  if (rateLimitResponse) {
 88→    return rateLimitResponse;
 89→  }
 90→
 91→  try {
 92→    const { searchParams } = new URL(request.url);
 93→    // Accept both 'q' and 'query' parameters for flexibility
 94→    const query = searchParams.get('q') || searchParams.get('query') || '';
 95→    const category = searchParams.get('category');
 96→    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '10', 10), 100);
 97→
 98→    // Parse excludeIds to filter out tools already in user's collection
 99→    const excludeIdsParam = searchParams.get('excludeIds');
100→    const excludeIds = excludeIdsParam ? excludeIdsParam.split(',').filter(Boolean) : [];
101→
102→    // Get recent messages for context (passed as JSON in 'messages' param)
103→    // Wrap in try-catch to handle malformed JSON gracefully
104→    const messagesParam = searchParams.get('messages');
105→    let recentMessages: string[] = [];
106→    if (messagesParam) {
107→      try {
108→        const parsed = JSON.parse(messagesParam);
109→        if (Array.isArray(parsed)) {
110→          recentMessages = parsed.filter((m): m is string => typeof m === 'string');
111→        }
112→      } catch {
113→        console.warn('[SEARCH API] Failed to parse messages param, ignoring');
114→      }
115→    }
116→
117→    console.log(
118→      `🔎 [SEARCH API] Query: "${query}", Category: ${category}, Limit: ${limit}, Messages: ${recentMessages.length}`
119→    );
120→
121→    // Extract search tokens for database-level pre-filtering
122→    const searchTokens = tokenize(query).filter((t) => t.length >= 2);
123→    const hasSearchQuery = searchTokens.length > 0;
124→
125→    // Build database filter - pre-filter at DB level to reduce in-memory processing
126→    // Use OR conditions to find tools that match ANY search token
127→    const dbFilter = {
128→      // Exclude tools already in collection (if provided)
129→      ...(excludeIds.length > 0 && { id: { notIn: excludeIds } }),
130→      ...(category && { package: { category } }),
131→      ...(hasSearchQuery && {
132→        OR: [
133→          // Match tool name
134→          { name: { contains: query, mode: 'insensitive' as const } },
135→          // Match tool description
136→          { description: { contains: query, mode: 'insensitive' as const } },
137→          // Match package name
138→          { package: { npmPackageName: { contains: query, mode: 'insensitive' as const } } },
139→          // Match package description
140→          { package: { npmDescription: { contains: query, mode: 'insensitive' as const } } },
141→          // Also try individual tokens for partial matches
142→          ...searchTokens
143→            .slice(0, 3)
144→            .flatMap((token) => [
145→              { name: { contains: token, mode: 'insensitive' as const } },
146→              { description: { contains: token, mode: 'insensitive' as const } },
147→            ]),
148→        ],
149→      }),
150→    };
151→
152→    // Fetch filtered tools with package info (max 500 for BM25 scoring)
153→    const tools = await prisma.tool.findMany({
154→      include: { package: true },
155→      where: dbFilter,
156→      take: hasSearchQuery ? 500 : 100, // Limit results for performance
157→      orderBy: hasSearchQuery ? undefined : { qualityScore: 'desc' },
158→    });
159→
160→    console.log(`📊 [SEARCH API] Found ${tools.length} tools in database`);
161→
162→    // Combine query with recent messages for better context
163→    const fullQuery = [query, ...recentMessages].filter(Boolean).join(' ');
164→    console.log(`🔍 [SEARCH API] Full search context: "${fullQuery.slice(0, 100)}..."`);
165→
166→    // Build all documents first
167→    const documents = tools.map((tool) => ({
168→      tool,
169→      text: [
170→        tool.description,
171→        tool.name,
172→        tool.package.npmPackageName,
173→        tool.package.npmDescription || '',
174→        ...(tool.package.npmKeywords || []),
175→      ].join(' '),
176→    }));
177→
178→    // Calculate document frequencies (IDF)
179→    const docFrequencies = new Map<string, number>();
180→    const queryTokens = tokenize(fullQuery);
181→
182→    for (const term of queryTokens) {
183→      let count = 0;
184→      for (const doc of documents) {
185→        const docTokens = tokenize(doc.text);
186→        if (docTokens.includes(term)) {
187→          count++;
188→        }
189→      }
190→      docFrequencies.set(term, count);
191→    }
192→
193→    // Calculate average document length
194→    const totalTokens = documents.reduce((sum, doc) => sum + tokenize(doc.text).length, 0);
195→    const avgDocLength = totalTokens / documents.length;
196→
197→    // Calculate BM25 scores
198→    const scoredResults = documents.map(({ tool, text }) => {
199→      const bm25Score = calculateBM25(fullQuery, text, avgDocLength, tools.length, docFrequencies);
200→      const qualityBoost = Number(tool.qualityScore ?? 0) * 0.5;
201→      const downloadBoost = Math.log10((tool.package.npmDownloadsLastMonth || 0) + 1) * 0.1;
202→
203→      // Massive boost for exact tool name match (when user mentions tool by name)
204→      const exactNameBoost = hasExactNameMatch(query, tool.name) ? 100 : 0;
205→
206→      // Boost for package name match (when user searches by package name like @tpmjs/tools-unsandbox)
207→      const packageNameBoost = hasPackageNameMatch(query, tool.package.npmPackageName) ? 50 : 0;
208→
209→      const finalScore =
210→        bm25Score + qualityBoost + downloadBoost + exactNameBoost + packageNameBoost;
211→
212→      return { tool, score: finalScore };
213→    });
214→
215→    // Sort by score and take top N
216→    const topResults = scoredResults
217→      .filter(({ score }) => score > 0) // Only include results with matches
218→      .sort((a, b) => b.score - a.score)
219→      .slice(0, limit + 1);
220→
221→    const hasMore = topResults.length > limit;
222→    const results = hasMore ? topResults.slice(0, limit) : topResults;
223→
224→    console.log(`✅ [SEARCH API] Returning ${results.length} results (hasMore: ${hasMore})`);
225→
226→    // Format response to match existing /api/tools structure
227→    return NextResponse.json({
228→      success: true,
229→      query,
230→      filters: { category },
231→      results: {
232→        total: scoredResults.filter(({ score }) => score > 0).length,
233→        returned: results.length,
234→        tools: results.map(({ tool }) => ({
235→          id: tool.id,
236→          name: tool.name,
237→          description: tool.description,
238→          inputSchema: tool.inputSchema,
239→          qualityScore: tool.qualityScore,
240→          importHealth: tool.importHealth,
241→          executionHealth: tool.executionHealth,
242→          healthCheckError: tool.healthCheckError,
243→          lastHealthCheck: tool.lastHealthCheck,
244→          package: {
245→            npmPackageName: tool.package.npmPackageName,
246→            npmVersion: tool.package.npmVersion,
247→            category: tool.package.category,
248→            frameworks: tool.package.frameworks,
249→            env: tool.package.env,
250→            npmRepository: tool.package.npmRepository,
251→            isOfficial: tool.package.isOfficial,
252→            npmDownloadsLastMonth: tool.package.npmDownloadsLastMonth,
253→          },
254→          importUrl: `https://esm.sh/${tool.package.npmPackageName}@${tool.package.npmVersion}`,
255→          cdnUrl: `https://cdn.jsdelivr.net/npm/${tool.package.npmPackageName}@${tool.package.npmVersion}/+esm`,
256→        })),
257→      },
258→      pagination: {
259→        limit,
260→        hasMore,
261→      },
262→    });
263→  } catch (error) {
264→    console.error('❌ [SEARCH API] Error:', error);
265→    return NextResponse.json(
266→      {
267→        success: false,
268→        error: error instanceof Error ? error.message : 'Search failed',
269→      },
270→      { status: 500 }
271→    );
272→  }
273→}
