554→// Stat Card Component
555→function StatCard({
556→  label,
557→  value,
558→  icon,
559→  prefix = '',
560→  suffix = '',
561→  decimals = 0,
562→  color = 'text-foreground',
563→}: {
564→  label: string;
565→  value: number;
566→  icon?: string;
567→  prefix?: string;
568→  suffix?: string;
569→  decimals?: number;
570→  color?: string;
571→}) {
572→  return (
573→    <div className="bg-surface border border-border rounded-xl p-4 hover:border-border-hover transition-colors">
574→      <div className="flex items-center gap-2 mb-2">
575→        {icon && <span className="text-lg">{icon}</span>}
576→        <span className="text-sm text-foreground-secondary">{label}</span>
577→      </div>
578→      <div className={`text-2xl font-bold ${color}`}>
579→        <AnimatedCounter value={value} prefix={prefix} suffix={suffix} decimals={decimals} />
580→      </div>
581→    </div>
582→  );
583→}
584→
585→// Chart Card Wrapper
586→function ChartCard({ title, children }: { title?: string; children: React.ReactNode }) {
587→  return (
588→    <div className="bg-surface border border-border rounded-xl p-6">
589→      {title && <h4 className="text-sm font-semibold text-foreground mb-4">{title}</h4>}
590→      <div className="flex justify-center">{children}</div>
591→    </div>
592→  );
593→}
