 73→export default function ActivityPage(): React.ReactElement {
 74→  const router = useRouter();
 75→  const [data, setData] = useState<DashboardData | null>(null);
 76→  const [activities, setActivities] = useState<ActivityItem[]>([]);
 77→  const [isLoading, setIsLoading] = useState(true);
 78→  const [isLoadingActivities, setIsLoadingActivities] = useState(false);
 79→  const [error, setError] = useState<string | null>(null);
 80→  const [period, setPeriod] = useState<Period>('30d');
 81→  const [activityFilter, setActivityFilter] = useState<ActivityFilter>('all');
 82→  const [activityCursor, setActivityCursor] = useState<string | null>(null);
 83→  const [hasMoreActivities, setHasMoreActivities] = useState(false);
 84→
 85→  const fetchDashboard = useCallback(async () => {
 86→    setIsLoading(true);
 87→    try {
 88→      const response = await fetch(`/api/user/activity-dashboard?period=${period}`);
 89→      const result = await response.json();
 90→      if (result.success) {
 91→        setData(result.data);
 92→        setError(null);
 93→      } else {
 94→        if (response.status === 401) {
 95→          router.push('/sign-in');
 96→          return;
 97→        }
 98→        setError(result.error || 'Failed to fetch dashboard');
 99→      }
100→    } catch {
101→      setError('Failed to fetch dashboard');
102→    } finally {
103→      setIsLoading(false);
104→    }
105→  }, [period, router]);
106→
107→  const fetchActivities = useCallback(
108→    async (cursor?: string | null) => {
109→      setIsLoadingActivities(true);
110→      try {
111→        const params = new URLSearchParams({ limit: '20' });
112→        if (activityFilter !== 'all') params.set('targetType', activityFilter);
113→        if (cursor) params.set('cursor', cursor);
114→
115→        const response = await fetch(`/api/user/activity?${params}`);
116→        const result = await response.json();
117→        if (result.success) {
118→          if (cursor) {
119→            setActivities((prev) => [...prev, ...result.data]);
120→          } else {
121→            setActivities(result.data);
122→          }
123→          setHasMoreActivities(result.pagination.hasMore);
124→          setActivityCursor(result.pagination.nextCursor ?? null);
125→        }
126→      } catch {
127→        // Silent fail for activity feed
128→      } finally {
129→        setIsLoadingActivities(false);
130→      }
131→    },
132→    [activityFilter]
133→  );
134→
135→  useEffect(() => {
136→    fetchDashboard();
137→  }, [fetchDashboard]);
138→
139→  useEffect(() => {
140→    setActivityCursor(null);
141→    fetchActivities();
142→  }, [fetchActivities]);
