 45→
 46→type Period = 'hourly' | 'daily' | 'monthly';
 47→
 48→function formatNumber(num: number): string {
 49→  if (num >= 1000000) return `${(num / 1000000).toFixed(1)}M`;
 50→  if (num >= 1000) return `${(num / 1000).toFixed(1)}K`;
 51→  return num.toString();
 52→}
 53→
 54→function formatCost(cents: number): string {
 55→  if (cents === 0) return '$0.00';
 56→  return `$${(cents / 100).toFixed(2)}`;
 57→}
