 1→// eslint-disable-next-line import/no-internal-modules
 2→import useSWRInfinite from 'swr/infinite';
 3→
 4→export interface Activity {
 5→  id: string;
 6→  type: string;
 7→  metadata: Record<string, unknown>;
 8→  createdAt: string;
 9→  tool?: {
10→    name: string;
11→    package: { npmPackageName: string };
12→  };
13→  agent?: {
14→    name: string;
15→    uid: string;
16→  };
17→  collection?: {
18→    name: string;
19→    uid: string;
20→  };
21→}
22→
23→interface ActivityResponse {
24→  activities: Activity[];
25→  pagination: {
26→    nextCursor: string | null;
27→  };
28→}
29→
30→/**
31→ * Infinite scroll hook for user activity stream
32→ */
33→export function useActivity(limit = 20) {
34→  const getKey = (pageIndex: number, previousPageData: ActivityResponse | null) => {
35→    // Reached the end
36→    if (previousPageData && !previousPageData.pagination.nextCursor) {
37→      return null;
38→    }
39→
40→    // First page
41→    if (pageIndex === 0) {
42→      return `/api/user/activity?limit=${limit}`;
43→    }
44→
45→    // Next pages
46→    const cursor = previousPageData?.pagination.nextCursor;
47→    return `/api/user/activity?limit=${limit}&cursor=${cursor}`;
48→  };
49→
50→  const { data, error, isLoading, isValidating, size, setSize, mutate } =
51→    useSWRInfinite<ActivityResponse>(
52→      getKey,
53→      async (url: string) => {
54→        const res = await fetch(url);
55→        const json = await res.json();
56→
57→        if (!json.success) {
58→          throw new Error(json.error || 'Failed to fetch activity');
59→        }
60→
61→        return {
62→          activities: json.data,
63→          pagination: json.pagination,
64→        };
65→      },
66→      {
67→        revalidateFirstPage: false,
68→      }
69→    );
70→
71→  // Flatten all activities from all pages
72→  const activities = data ? data.flatMap((page: ActivityResponse) => page.activities) : [];
73→
74→  // Check if there are more pages
75→  const hasMore = data ? data[data.length - 1]?.pagination.nextCursor !== null : false;
76→
77→  const loadMore = () => {
78→    if (hasMore && !isValidating) {
79→      setSize(size + 1);
80→    }
81→  };
82→
83→  return {
84→    activities,
85→    isLoading,
86→    isLoadingMore: isValidating && data && data.length > 0,
87→    error,
88→    hasMore,
89→    loadMore,
90→    mutate,
91→  };
92→}
