 1→'use client';
 2→
 3→import { useEffect, useRef, useState } from 'react';
 4→
 5→interface AnimatedCounterProps {
 6→  value: number;
 7→  duration?: number;
 8→  prefix?: string;
 9→  suffix?: string;
10→  decimals?: number;
11→  className?: string;
12→}
13→
14→export function AnimatedCounter({
15→  value,
16→  duration = 1500,
17→  prefix = '',
18→  suffix = '',
19→  decimals = 0,
20→  className = '',
21→}: AnimatedCounterProps): React.ReactElement {
22→  const [displayValue, setDisplayValue] = useState(0);
23→  const startTimeRef = useRef<number | null>(null);
24→  const frameRef = useRef<number | null>(null);
25→
26→  useEffect(() => {
27→    const startValue = 0;
28→    const endValue = value;
29→
30→    const animate = (timestamp: number) => {
31→      if (!startTimeRef.current) {
32→        startTimeRef.current = timestamp;
33→      }
34→
35→      const elapsed = timestamp - startTimeRef.current;
36→      const progress = Math.min(elapsed / duration, 1);
37→
38→      // Easing function (ease-out-expo)
39→      const easeOutExpo = 1 - 2 ** (-10 * progress);
40→      const current = startValue + (endValue - startValue) * easeOutExpo;
41→
42→      setDisplayValue(current);
43→
44→      if (progress < 1) {
45→        frameRef.current = requestAnimationFrame(animate);
46→      }
47→    };
48→
49→    frameRef.current = requestAnimationFrame(animate);
50→
51→    return () => {
52→      if (frameRef.current) {
53→        cancelAnimationFrame(frameRef.current);
54→      }
55→    };
56→  }, [value, duration]);
57→
58→  const formatNumber = (num: number): string => {
59→    if (decimals > 0) {
60→      return num.toFixed(decimals);
61→    }
62→
63→    // Format with commas
64→    return Math.round(num).toLocaleString();
65→  };
66→
67→  return (
68→    <span className={className}>
69→      {prefix}
70→      {formatNumber(displayValue)}
71→      {suffix}
72→    </span>
73→  );
74→}
