  1→'use client';
  2→
  3→import * as d3 from 'd3';
  4→import { useEffect, useRef, useState } from 'react';
  5→
  6→interface DonutChartProps {
  7→  data: { label: string; value: number; color: string }[];
  8→  size?: number;
  9→  innerRadius?: number;
 10→  title?: string;
 11→  centerValue?: string | number;
 12→  centerLabel?: string;
 13→}
 14→
 15→function getThemeColors(element: HTMLElement) {
 16→  const styles = getComputedStyle(element);
 17→  return {
 18→    background: styles.getPropertyValue('--color-background').trim() || '#ffffff',
 19→    foreground: styles.getPropertyValue('--color-foreground').trim() || '#0a0a0a',
 20→    foregroundSecondary:
 21→      styles.getPropertyValue('--color-foreground-secondary').trim() || '#525252',
 22→  };
 23→}
 24→
 25→export function DonutChart({
 26→  data,
 27→  size = 200,
 28→  innerRadius = 0.6,
 29→  title,
 30→  centerValue,
 31→  centerLabel,
 32→}: DonutChartProps): React.ReactElement {
 33→  const svgRef = useRef<SVGSVGElement>(null);
 34→  const containerRef = useRef<HTMLDivElement>(null);
 35→  const [hoveredSlice, setHoveredSlice] = useState<string | null>(null);
 36→
 37→  useEffect(() => {
 38→    if (!svgRef.current || !containerRef.current || data.length === 0) return;
 39→
 40→    const colors = getThemeColors(containerRef.current);
 41→    const svg = d3.select(svgRef.current);
 42→    svg.selectAll('*').remove();
 43→
 44→    const radius = size / 2;
 45→    const innerR = radius * innerRadius;
 46→
 47→    const g = svg
 48→      .attr('width', size)
 49→      .attr('height', size)
 50→      .append('g')
 51→      .attr('transform', `translate(${radius}, ${radius})`);
 52→
 53→    const pie = d3
 54→      .pie<{ label: string; value: number; color: string }>()
 55→      .value((d) => d.value)
 56→      .sort(null)
 57→      .padAngle(0.02);
 58→
 59→    const arc = d3
 60→      .arc<d3.PieArcDatum<{ label: string; value: number; color: string }>>()
 61→      .innerRadius(innerR)
 62→      .outerRadius(radius - 10);
 63→
 64→    const hoverArc = d3
 65→      .arc<d3.PieArcDatum<{ label: string; value: number; color: string }>>()
 66→      .innerRadius(innerR)
 67→      .outerRadius(radius - 5);
 68→
 69→    const arcs = pie(data);
 70→
 71→    // Draw slices with animation
 72→    g.selectAll('path')
 73→      .data(arcs)
 74→      .enter()
 75→      .append('path')
 76→      .attr('fill', (d) => d.data.color)
 77→      .attr('stroke', colors.background)
 78→      .attr('stroke-width', 2)
 79→      .style('cursor', 'pointer')
 80→      .style('opacity', 0.9)
 81→      .on('mouseenter', function (_, d) {
 82→        setHoveredSlice(d.data.label);
 83→        d3.select(this)
 84→          .transition()
 85→          .duration(200)
 86→          .attr('d', hoverArc as unknown as string)
 87→          .style('opacity', 1);
 88→      })
 89→      .on('mouseleave', function () {
 90→        setHoveredSlice(null);
 91→        d3.select(this)
 92→          .transition()
 93→          .duration(200)
 94→          .attr('d', arc as unknown as string)
 95→          .style('opacity', 0.9);
 96→      })
 97→      .transition()
 98→      .duration(800)
 99→      .attrTween('d', (d) => {
100→        const interpolate = d3.interpolate({ startAngle: 0, endAngle: 0 }, d);
101→        return (t) => arc(interpolate(t)) || '';
102→      });
103→
104→    // Center text
105→    if (centerValue !== undefined) {
106→      g.append('text')
107→        .attr('text-anchor', 'middle')
108→        .attr('dominant-baseline', 'middle')
109→        .attr('dy', centerLabel ? '-0.3em' : '0')
110→        .attr('fill', colors.foreground)
111→        .style('font-size', '1.5rem')
112→        .style('font-weight', 'bold')
113→        .text(String(centerValue));
114→
115→      if (centerLabel) {
116→        g.append('text')
117→          .attr('text-anchor', 'middle')
118→          .attr('dominant-baseline', 'middle')
119→          .attr('dy', '1.2em')
120→          .attr('fill', colors.foregroundSecondary)
121→          .style('font-size', '0.75rem')
122→          .text(centerLabel);
123→      }
124→    }
125→  }, [data, size, innerRadius, centerValue, centerLabel]);
126→
127→  const total = data.reduce((sum, d) => sum + d.value, 0);
128→  const hoveredData = data.find((d) => d.label === hoveredSlice);
129→
130→  return (
131→    <div ref={containerRef} className="flex flex-col items-center">
132→      {title && <h4 className="text-sm font-semibold text-foreground mb-3">{title}</h4>}
133→      <div className="relative">
134→        <svg ref={svgRef} />
135→        {hoveredData && (
136→          <div className="absolute top-full left-1/2 -translate-x-1/2 mt-2 px-3 py-1.5 bg-surface border border-border rounded-lg shadow-lg text-sm whitespace-nowrap z-10">
137→            <span className="font-medium text-foreground">{hoveredData.label}:</span>{' '}
138→            <span className="text-foreground-secondary">
139→              {hoveredData.value.toLocaleString()} ({((hoveredData.value / total) * 100).toFixed(1)}
140→              %)
141→            </span>
142→          </div>
143→        )}
144→      </div>
145→      <div className="flex flex-wrap justify-center gap-3 mt-4">
146→        {data.map((d) => (
147→          <div
148→            key={d.label}
149→            className={`flex items-center gap-1.5 text-xs transition-opacity ${
150→              hoveredSlice && hoveredSlice !== d.label ? 'opacity-50' : 'opacity-100'
151→            }`}
152→          >
153→            <span className="w-3 h-3 rounded-full" style={{ backgroundColor: d.color }} />
154→            <span className="text-foreground-secondary">{d.label}</span>
155→          </div>
156→        ))}
157→      </div>
158→    </div>
159→  );
160→}
