 32→ *         variant="brutalist"
 33→ *         showBar
 34→ *         barProgress={85}
 35→ *       />
 36→ *       <StatCard
 37→ *         value={48000}
 38→ *         suffix="+"
 39→ *         label="Active Developers"
 40→ *         variant="default"
 41→ *       />
 42→ *     </div>
 43→ *   );
 44→ * }
 45→ * ```
 46→ */
 47→export const StatCard = forwardRef<HTMLDivElement, StatCardProps>(
 48→  (
 49→    {
 50→      className,
 51→      value,
 52→      label,
 53→      subtext,
