  1→import type { UserTier } from '@prisma/client';
  2→import { kv } from '@vercel/kv';
  3→import { RATE_LIMITS_BY_TIER } from './index';
  4→
  5→/**
  6→ * Rate limiting for API keys using Vercel KV
  7→ *
  8→ * Each API key has a rate limit based on the user's tier.
  9→ * Limits are enforced per hour (rolling window).
 10→ */
 11→
 12→// Check if Vercel KV is available
 13→const isKVAvailable = !!process.env.KV_REST_API_URL;
 14→
 15→// In-memory fallback for development
 16→const memoryStore = new Map<string, { count: number; windowStart: number }>();
 17→
 18→/**
 19→ * Result of a rate limit check
 20→ */
 21→export interface RateLimitResult {
 22→  /** Whether the request is allowed */
 23→  allowed: boolean;
 24→  /** Remaining requests in the current window */
 25→  remaining: number;
 26→  /** When the rate limit resets (window end) */
 27→  resetAt: Date;
 28→  /** Total limit for the window */
 29→  limit: number;
 30→  /** Current request count in window */
 31→  current: number;
 32→}
 33→
 34→/**
 35→ * Get the hourly window start time (aligned to clock hour)
 36→ */
 37→function getHourlyWindowStart(): number {
 38→  const now = Date.now();
 39→  const hourMs = 60 * 60 * 1000;
 40→  return Math.floor(now / hourMs) * hourMs;
 41→}
 42→
 43→/**
 44→ * Check rate limit for an API key using Vercel KV
 45→ *
 46→ * @param identifier - API key ID or user ID (for session auth)
 47→ * @param tier - User's tier for determining rate limit
 48→ * @param customLimit - Optional custom limit (overrides tier default)
 49→ * @returns RateLimitResult with allowed status and metadata
 50→ *
 51→ * @example
 52→ * const result = await checkApiKeyRateLimit(apiKeyId, 'FREE');
 53→ * if (!result.allowed) {
 54→ *   return new Response(JSON.stringify({ error: 'Rate limit exceeded' }), { status: 429 });
 55→ * }
 56→ */
 57→export async function checkApiKeyRateLimit(
 58→  identifier: string,
 59→  tier: UserTier,
 60→  customLimit?: number | null
 61→): Promise<RateLimitResult> {
 62→  const limit = customLimit ?? RATE_LIMITS_BY_TIER[tier];
 63→  const windowMs = 60 * 60 * 1000; // 1 hour
 64→  const windowStart = getHourlyWindowStart();
 65→  const windowEnd = windowStart + windowMs;
 66→  const resetAt = new Date(windowEnd);
 67→
 68→  const key = `apikey:ratelimit:${identifier}:${windowStart}`;
 69→
 70→  if (isKVAvailable) {
 71→    return checkRateLimitKV(key, limit, windowMs, resetAt);
 72→  }
 73→
 74→  return checkRateLimitMemory(key, limit, windowStart, resetAt);
 75→}
 76→
 77→/**
 78→ * Check rate limit using Vercel KV (distributed)
 79→ */
 80→async function checkRateLimitKV(
 81→  key: string,
 82→  limit: number,
 83→  windowMs: number,
 84→  resetAt: Date
 85→): Promise<RateLimitResult> {
 86→  try {
 87→    // Increment counter atomically
 88→    const current = await kv.incr(key);
 89→
 90→    // Set expiry on first request in window
 91→    if (current === 1) {
 92→      await kv.expire(key, Math.ceil(windowMs / 1000) + 60); // Add 60s buffer
 93→    }
 94→
 95→    const remaining = Math.max(0, limit - current);
 96→    const allowed = current <= limit;
 97→
 98→    return {
 99→      allowed,
100→      remaining,
101→      resetAt,
102→      limit,
103→      current,
104→    };
105→  } catch (error) {
106→    console.error('[API Key Rate Limit] KV error:', error);
107→    // On error, allow the request but log the issue
108→    return {
109→      allowed: true,
110→      remaining: limit,
111→      resetAt,
112→      limit,
113→      current: 0,
114→    };
115→  }
116→}
117→
118→/**
119→ * Check rate limit using in-memory store (fallback)
120→ */
121→function checkRateLimitMemory(
122→  key: string,
123→  limit: number,
124→  windowStart: number,
125→  resetAt: Date
126→): RateLimitResult {
127→  let entry = memoryStore.get(key);
128→
129→  // Reset if window has changed
130→  if (!entry || entry.windowStart !== windowStart) {
131→    entry = { count: 0, windowStart };
132→    memoryStore.set(key, entry);
133→  }
134→
135→  // Increment count
136→  entry.count++;
137→
138→  const remaining = Math.max(0, limit - entry.count);
139→  const allowed = entry.count <= limit;
140→
141→  // Cleanup old entries periodically
142→  if (Math.random() < 0.01) {
143→    // 1% chance per request
144→    cleanupMemoryStore(windowStart);
145→  }
146→
147→  return {
148→    allowed,
149→    remaining,
150→    resetAt,
151→    limit,
152→    current: entry.count,
153→  };
154→}
155→
156→/**
157→ * Cleanup old entries from memory store
158→ */
159→function cleanupMemoryStore(currentWindowStart: number): void {
160→  for (const [key, entry] of memoryStore.entries()) {
161→    if (entry.windowStart < currentWindowStart) {
162→      memoryStore.delete(key);
163→    }
164→  }
165→}
166→
167→/**
168→ * Get rate limit headers for a response
169→ *
170→ * @param result - Rate limit result
171→ * @returns Headers object to add to response
172→ */
173→export function getRateLimitHeaders(result: RateLimitResult): Record<string, string> {
174→  return {
175→    'X-RateLimit-Limit': result.limit.toString(),
176→    'X-RateLimit-Remaining': result.remaining.toString(),
177→    'X-RateLimit-Reset': Math.ceil(result.resetAt.getTime() / 1000).toString(),
178→  };
179→}
180→
181→/**
182→ * Create a rate limited response (429)
183→ *
184→ * @param result - Rate limit result
185→ * @returns Response with 429 status and rate limit headers
186→ */
187→export function createRateLimitResponse(result: RateLimitResult): Response {
188→  const retryAfterSeconds = Math.ceil((result.resetAt.getTime() - Date.now()) / 1000);
189→
190→  return new Response(
191→    JSON.stringify({
192→      error: 'Rate limit exceeded',
193→      message: `Too many requests. Please try again in ${retryAfterSeconds} seconds.`,
194→      retryAfter: retryAfterSeconds,
195→      limit: result.limit,
196→      remaining: 0,
197→      resetAt: result.resetAt.toISOString(),
198→    }),
199→    {
200→      status: 429,
201→      headers: {
202→        'Content-Type': 'application/json',
203→        'Retry-After': retryAfterSeconds.toString(),
204→        ...getRateLimitHeaders(result),
205→      },
206→    }
207→  );
208→}
