  3→import type { ActivityType } from '@prisma/client';
  4→import { Icon, type IconName } from '@tpmjs/ui/Icon/Icon';
  5→import { Spinner } from '@tpmjs/ui/Spinner/Spinner';
  6→import { useCallback, useEffect, useRef, useState } from 'react';
  7→import { Virtuoso } from 'react-virtuoso';
  8→import { ACTIVITY_ICONS, ACTIVITY_MESSAGES } from '~/lib/activity';
  9→
 10→interface Activity {
 11→  id: string;
 12→  type: ActivityType;
 13→  targetName: string;
 14→  targetType: string;
 15→  agentId: string | null;
 16→  collectionId: string | null;
 17→  toolId: string | null;
 18→  metadata: Record<string, unknown> | null;
 19→  createdAt: string;
 20→}
 21→
 22→interface ActivityResponse {
 23→  success: boolean;
 24→  data: Activity[];
 25→  pagination: {
 26→    limit: number;
 27→    hasMore: boolean;
 28→    nextCursor: string | null;
 29→  };
 30→}
 31→
 32→function formatRelativeTime(dateString: string): string {
 33→  const date = new Date(dateString);
 34→  const now = new Date();
 35→  const diffMs = now.getTime() - date.getTime();
 36→  const diffSeconds = Math.floor(diffMs / 1000);
 37→  const diffMinutes = Math.floor(diffSeconds / 60);
 38→  const diffHours = Math.floor(diffMinutes / 60);
 39→  const diffDays = Math.floor(diffHours / 24);
 40→
 41→  if (diffSeconds < 60) return 'just now';
 42→  if (diffMinutes < 60) return `${diffMinutes}m ago`;
 43→  if (diffHours < 24) return `${diffHours}h ago`;
 44→  if (diffDays < 7) return `${diffDays}d ago`;
 45→
 46→  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
 47→}
