 49→// Map activity icons to available IconName values
 50→const iconMapping: Record<string, IconName> = {
 51→  plus: 'plus',
 52→  pencil: 'edit',
 53→  trash: 'trash',
 54→  link: 'link',
 55→  unlink: 'x',
 56→  folderPlus: 'folder',
 57→  folderMinus: 'folder',
 58→  heart: 'heart',
 59→  heartOff: 'heart',
 60→};
 61→
 62→function getActivityIcon(type: ActivityType): IconName {
 63→  const iconKey = ACTIVITY_ICONS[type];
 64→  return iconMapping[iconKey] || 'info';
 65→}
 66→
 67→function getActivityMessage(activity: Activity): string {
 68→  const messageGetter = ACTIVITY_MESSAGES[activity.type];
 69→  if (!messageGetter) return `Unknown activity: ${activity.type}`;
 70→  return messageGetter(activity.targetName, activity.metadata ?? undefined);
 71→}
