 73→interface DashboardActivityStreamProps {
 74→  className?: string;
 75→  autoRefreshInterval?: number; // milliseconds, 0 to disable
 76→}
 77→
 78→export function DashboardActivityStream({
 79→  className = '',
 80→  autoRefreshInterval = 30000,
 81→}: DashboardActivityStreamProps): React.ReactElement {
 82→  const [activities, setActivities] = useState<Activity[]>([]);
 83→  const [loading, setLoading] = useState(true);
 84→  const [loadingMore, setLoadingMore] = useState(false);
 85→  const [hasMore, setHasMore] = useState(false);
 86→  const [error, setError] = useState<string | null>(null);
 87→  const nextCursorRef = useRef<string | null>(null);
 88→
 89→  const fetchActivities = useCallback(async (cursor?: string | null) => {
 90→    try {
 91→      const params = new URLSearchParams({ limit: '20' });
 92→      if (cursor) params.set('cursor', cursor);
 93→
 94→      const response = await fetch(`/api/user/activity?${params.toString()}`);
 95→      const data: ActivityResponse = await response.json();
 96→
 97→      if (!data.success) {
 98→        throw new Error('Failed to fetch activities');
 99→      }
100→
101→      return data;
102→    } catch (err) {
103→      throw err instanceof Error ? err : new Error('Unknown error');
104→    }
105→  }, []);
106→
107→  // Initial load
108→  useEffect(() => {
109→    let cancelled = false;
110→
111→    async function load() {
112→      try {
113→        setLoading(true);
114→        setError(null);
115→        const data = await fetchActivities();
116→        if (!cancelled) {
117→          setActivities(data.data);
118→          setHasMore(data.pagination.hasMore);
119→          nextCursorRef.current = data.pagination.nextCursor;
120→        }
121→      } catch (err) {
122→        if (!cancelled) {
123→          setError(err instanceof Error ? err.message : 'Failed to load activities');
124→        }
125→      } finally {
126→        if (!cancelled) {
127→          setLoading(false);
128→        }
129→      }
130→    }
131→
132→    load();
133→    return () => {
134→      cancelled = true;
135→    };
136→  }, [fetchActivities]);
137→
138→  // Auto-refresh
139→  useEffect(() => {
140→    if (autoRefreshInterval <= 0) return;
141→
142→    const interval = setInterval(async () => {
143→      try {
144→        const data = await fetchActivities();
145→        setActivities(data.data);
146→        setHasMore(data.pagination.hasMore);
147→        nextCursorRef.current = data.pagination.nextCursor;
148→      } catch {
149→        // Silent fail on auto-refresh
150→      }
151→    }, autoRefreshInterval);
152→
153→    return () => clearInterval(interval);
154→  }, [autoRefreshInterval, fetchActivities]);
155→
156→  const loadMore = useCallback(async () => {
157→    if (loadingMore || !hasMore || !nextCursorRef.current) return;
158→
159→    try {
160→      setLoadingMore(true);
161→      const data = await fetchActivities(nextCursorRef.current);
162→      setActivities((prev) => [...prev, ...data.data]);
163→      setHasMore(data.pagination.hasMore);
164→      nextCursorRef.current = data.pagination.nextCursor;
165→    } catch {
166→      // Silent fail on load more
167→    } finally {
168→      setLoadingMore(false);
169→    }
170→  }, [loadingMore, hasMore, fetchActivities]);
171→
172→  if (loading) {
173→    return (
174→      <div className={`flex items-center justify-center py-12 ${className}`}>
175→        <Spinner size="md" />
176→        <span className="ml-2 text-foreground-secondary text-sm">Loading activity...</span>
177→      </div>
178→    );
179→  }
180→
181→  if (error) {
182→    return (
183→      <div className={`text-center py-8 ${className}`}>
184→        <Icon icon="alertCircle" size="lg" className="text-foreground-tertiary mx-auto mb-2" />
185→        <p className="text-foreground-secondary text-sm">{error}</p>
186→      </div>
187→    );
188→  }
189→
190→  if (activities.length === 0) {
191→    return (
192→      <div className={`text-center py-8 ${className}`}>
193→        <Icon icon="clock" size="lg" className="text-foreground-tertiary mx-auto mb-2" />
194→        <p className="text-foreground-secondary text-sm">No activity yet</p>
195→        <p className="text-foreground-tertiary text-xs mt-1">
196→          Your activity will appear here when you create or modify agents, collections, or tools.
197→        </p>
198→      </div>
199→    );
200→  }
201→
202→  return (
203→    <div className={`${className}`}>
204→      <Virtuoso
205→        style={{ height: '400px' }}
206→        data={activities}
207→        endReached={loadMore}
208→        overscan={10}
209→        itemContent={(_, activity) => (
210→          <div className="flex items-start gap-3 py-3 border-b border-border last:border-0">
211→            <div className="flex-shrink-0 w-8 h-8 rounded-full bg-surface flex items-center justify-center">
212→              <Icon
213→                icon={getActivityIcon(activity.type)}
214→                size="sm"
215→                className="text-foreground-secondary"
216→              />
217→            </div>
218→            <div className="flex-1 min-w-0">
219→              <p className="text-sm text-foreground">{getActivityMessage(activity)}</p>
220→              <p className="text-xs text-foreground-tertiary mt-0.5">
221→                {formatRelativeTime(activity.createdAt)}
222→              </p>
223→            </div>
224→          </div>
225→        )}
226→        components={{
227→          Footer: () =>
228→            loadingMore ? (
229→              <div className="flex items-center justify-center py-4">
230→                <Spinner size="sm" />
231→              </div>
232→            ) : null,
233→        }}
234→      />
235→    </div>
236→  );
237→}
