 3→export interface TrackExecutionParams {
 4→  eventType: 'tool_call' | 'agent_run' | 'collection_use' | 'scenario_run';
 5→  source: 'mcp_http' | 'mcp_sse' | 'agent_chat' | 'ui_simulation' | 'scenario' | 'omega';
 6→  userId?: string;
 7→  apiKeyId?: string;
 8→  toolId?: string;
 9→  agentId?: string;
