21→/**
22→ * Track an execution event (fire-and-forget pattern).
23→ * Never throws - failures are logged but don't break the main operation.
24→ */
25→export function trackExecution(params: TrackExecutionParams): void {
26→  prisma.executionEvent
27→    .create({
28→      data: {
29→        eventType: params.eventType,
30→        source: params.source,
31→        userId: params.userId,
32→        apiKeyId: params.apiKeyId,
33→        toolId: params.toolId,
34→        agentId: params.agentId,
35→        collectionId: params.collectionId,
36→        toolName: params.toolName,
37→        packageName: params.packageName,
38→        status: params.status,
39→        durationMs: params.durationMs,
40→        tokensIn: params.tokensIn,
41→        tokensOut: params.tokensOut,
42→        errorCode: params.errorCode,
43→        errorMessage: params.errorMessage,
44→      },
45→    })
46→    .catch((error) => {
47→      console.error('[trackExecution] Failed to record execution event:', error);
48→    });
