 1→'use client';
 2→
 3→import { ActivityStream } from '@tpmjs/ui/ActivityStream/ActivityStream';
 4→import { useEffect, useRef, useState } from 'react';
 5→
 6→interface ActivityItem {
 7→  type: 'invoked' | 'published' | 'updated';
 8→  tool: string;
 9→  time: string;
10→}
11→
12→function formatRelativeTime(dateStr: string): string {
13→  const diff = Date.now() - new Date(dateStr).getTime();
14→  const seconds = Math.floor(diff / 1000);
15→
16→  if (seconds < 60) return `${seconds}s ago`;
17→  const minutes = Math.floor(seconds / 60);
18→  if (minutes < 60) return `${minutes}m ago`;
19→  const hours = Math.floor(minutes / 60);
20→  if (hours < 24) return `${hours}h ago`;
21→  const days = Math.floor(hours / 24);
22→  return `${days}d ago`;
23→}
24→
25→interface PublicActivity {
26→  id: string;
27→  type: 'invoked' | 'published' | 'updated';
28→  username: string;
29→  targetName: string;
30→  targetType: string;
31→  createdAt: string;
32→}
33→
34→export function PublicActivityStream(): React.ReactElement {
35→  const [activities, setActivities] = useState<ActivityItem[]>([]);
36→  const isMounted = useRef(true);
37→
38→  useEffect(() => {
39→    isMounted.current = true;
40→
41→    async function fetchActivities() {
42→      try {
43→        const res = await fetch('/api/activity/public');
44→        const json = await res.json();
45→
46→        if (isMounted.current && json.success && json.data.length > 0) {
47→          setActivities(
48→            json.data.map((a: PublicActivity) => ({
49→              type: a.type,
50→              tool: `${a.username} → ${a.targetName}`,
51→              time: formatRelativeTime(a.createdAt),
52→            }))
53→          );
54→        }
55→      } catch {
56→        // Silent fail — activity stream is non-critical
57→      }
58→    }
59→
60→    // Initial fetch via interval (fires immediately on mount delay, then every 30s)
61→    const timeoutId = setTimeout(fetchActivities, 0);
62→    const intervalId = setInterval(fetchActivities, 30_000);
63→
64→    return () => {
65→      isMounted.current = false;
66→      clearTimeout(timeoutId);
67→      clearInterval(intervalId);
68→    };
69→  }, []);
70→
71→  // Pass activities to the existing ActivityStream component
72→  // If no real activities exist yet, ActivityStream will auto-generate mock activity
73→  return (
74→    <ActivityStream
75→      activities={activities.length > 0 ? activities : undefined}
76→      updateInterval={30_000}
77→      maxItems={5}
78→    />
79→  );
80→}
