20→/**
21→ * GET /api/activity/public
22→ * Returns recent public activity for the homepage activity stream.
23→ * Cached for 30 seconds with stale-while-revalidate.
24→ */
25→export async function GET() {
26→  try {
27→    const activities = await prisma.userActivity.findMany({
28→      where: {
29→        type: { in: [...PUBLIC_ACTIVITY_TYPES] },
30→      },
31→      orderBy: { createdAt: 'desc' },
32→      take: 20,
33→      select: {
34→        id: true,
35→        type: true,
36→        targetName: true,
37→        targetType: true,
38→        createdAt: true,
39→        user: {
40→          select: {
41→            username: true,
42→            name: true,
43→          },
44→        },
45→      },
46→    });
47→
48→    const data = activities.map((a) => ({
49→      id: a.id,
50→      type: mapActivityType(a.type),
51→      username: a.user.username || a.user.name,
52→      targetName: a.targetName,
53→      targetType: a.targetType,
54→      createdAt: a.createdAt,
55→    }));
56→
57→    return NextResponse.json(
58→      { success: true, data },
59→      {
60→        headers: {
61→          'Cache-Control': 's-maxage=30, stale-while-revalidate=60',
62→        },
63→      }
64→    );
65→  } catch (error) {
66→    console.error('[activity/public] Error:', error);
67→    return NextResponse.json({ success: true, data: [] });
68→  }
69→}
